var Q30 = [
{n:1, q:'De conformidad con lo dispuesto en el art.2 de la Ley 17/2017, la coordinación de las policías locales tiene como objetivo:', o:{a:'Adecuar la formación, organización, dotación y actuación de las policías locales a los cometidos que tienen legalmente asignados en materia de seguridad pública.',b:'Garantizar la homogeneidad de sus recursos personales, técnicos y materiales.',c:'Mejorar su profesionalidad, eficacia y eficiencia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.2 de la Ley 17/2017 establece que los objetivos de la coordinación son todos los citados: adecuación, homogeneidad y mejora de la profesionalidad.'}},
{n:2, q:'El art.3 de la Ley 17/2017 establece las funciones de coordinación de los cuerpos de Policía Local de la Comunitat Valenciana. Indique cual de las siguientes no es una de ellas:', o:{a:'El establecimiento de un sistema bibliográfico, documental, de información legislativa y jurisprudencial, con atención preferente a la administración de justicia y a la policía local.',b:'Establecer una norma marco a la que deben ajustarse la estructura, la organización y el funcionamiento de los cuerpos de policía local.',c:'La fijación de las bases y los criterios uniformes para la formación, la selección, la promoción y la movilidad de las policías locales.',d:'La formación para el desarrollo profesional de quienes integran los cuerpos de policía local.'}, correct:'a', why:{a:'El art.3 Ley 17/2017 no incluye el sistema bibliográfico preferente a la administración de justicia como función de coordinación; esa función corresponde al IVASPE (art.16 Ley 17/2017).'}},
{n:3, q:'El art.3 de la Ley 17/2017 establece las funciones de coordinación de los cuerpos de Policía Local de la Comunitat Valenciana. Indique cual de las siguientes no es una de ellas:', o:{a:'La determinación del régimen de derechos y deberes y el régimen disciplinario de los miembros de los cuerpos de policía local.',b:'El establecimiento de un sistema bibliográfico, documental, de información legislativa y jurisprudencial, con atención preferente a la administración de justicia y a la policía local.',c:'La regulación de los sistemas de homogeneización y homologación de la uniformidad, equipos y medios técnicos de actuación.',d:'El impulso de un régimen retributivo conforme con la especificidad, la peculiaridad y otras circunstancias que definen la función policial.'}, correct:'b', why:{b:'El art.3 Ley 17/2017 no incluye el sistema bibliográfico preferente a la administración de justicia como función de coordinación. Corresponde al IVASPE (art.16).'}},
{n:4, q:'El art.3 de la Ley 17/2017 establece las funciones de coordinación de los cuerpos de Policía Local de la Comunitat Valenciana. Indique cual de las siguientes no es una de ellas:', o:{a:'La organización de un sistema de intercomunicaciones policiales que permita la máxima eficacia en las actuaciones.',b:'El establecimiento de un sistema bibliográfico, documental, de información legislativa y jurisprudencial, con atención preferente a la administración de justicia y a la policía local.',c:'La información y el asesoramiento a las entidades locales en materia de policía local.',d:'La creación del marco en el que se deberá desarrollar el apoyo y la colaboración entre policías locales en materia de información, actuaciones conjuntas y prestaciones recíprocas de carácter temporal y extraordinario.'}, correct:'b', why:{b:'Conforme al art.3 Ley 17/2017, el sistema bibliográfico preferente a la administración de justicia no es función de coordinación; corresponde al IVASPE (art.16).'}},
{n:5, q:'El art.3 de la Ley 17/2017 establece las funciones de coordinación de los cuerpos de Policía Local de la Comunitat Valenciana. Indique cual de las siguientes no es una de ellas:', o:{a:'El establecimiento de una red de transmisiones que enlace los diferentes cuerpos de policía local en un centro de coordinación.',b:'El establecimiento de un sistema bibliográfico, documental, de información legislativa y jurisprudencial, con atención preferente a la administración de justicia y a la policía local.',c:'El establecimiento de los medios necesarios para garantizar las funciones establecidas en esta ley.',d:'El establecimiento de un sistema de información recíproca entre los diversos cuerpos de policía local a través de la creación de una base de datos común.'}, correct:'b', why:{b:'El art.3 Ley 17/2017 no contempla el sistema bibliográfico preferente a la administración de justicia como función de coordinación. Corresponde al IVASPE (art.16).'}},
{n:6, q:'El art.3 de la Ley 17/2017 establece las funciones de coordinación de los cuerpos de Policía Local de la Comunitat Valenciana. Indique cual de las siguientes no es una de ellas:', o:{a:'El establecimiento de un sistema bibliográfico, documental, de información legislativa y jurisprudencial, con atención preferente a la administración de justicia y a la policía local.',b:'El impulso de la coordinación y la colaboración interadministrativa para la mejora de la prestación de los servicios en ámbitos supramunicipales o de servicios mancomunados.',c:'El impulso de la coordinación de las actuaciones de los municipios de la comunidad autónoma en materia de tráfico y seguridad viaria.',d:'Además de las previstas expresamente en dicho artículo, cualesquiera otras que pueda establecer el ordenamiento jurídico.'}, correct:'a', why:{a:'Conforme al art.3 Ley 17/2017, el sistema bibliográfico con atención preferente a la administración de justicia no es función de coordinación; corresponde al IVASPE (art.16).'}},
{n:7, q:'El art.3 de la Ley 17/2017 establece las funciones de coordinación de los cuerpos de Policía Local de la Comunitat Valenciana. Indique cual de las siguientes no es una de ellas:', o:{a:'La propuesta, en las comisiones autonómicas y provinciales de policía judicial, sobre los temas que afecten a las policías locales.',b:'El impulso de un régimen retributivo específico, acorde con la especialidad, la peligrosidad y otras circunstancias peculiares que influyen en la función policial.',c:'El establecimiento de un plan territorial en materia de seguridad local.',d:'La elaboración y publicación de las estadísticas anuales en materia de policía local.'}, correct:'b', why:{b:'Según el art.3 Ley 17/2017, el impulso de un régimen retributivo específico no figura como función de coordinación.'}},
{n:8, q:'El art.3 de la Ley 17/2017 establece las funciones de coordinación de los cuerpos de Policía Local de la Comunitat Valenciana. Indique cual de las siguientes no es una de ellas:', o:{a:'El impulso de un régimen retributivo específico, acorde con la especialidad, la peligrosidad y otras circunstancias peculiares que influyen en la función policial.',b:'El establecimiento de un sistema bibliográfico, documental, de información legislativa, con atención preferente a la administración municipal y a su policía local.',c:'Además de las previstas expresamente en dicho artículo, cualesquiera otras que pueda establecer el ordenamiento jurídico.',d:'La regulación del apoyo para las administraciones locales en la redacción o aplicación de los planes locales de seguridad.'}, correct:'a', why:{a:'El art.3 Ley 17/2017 no incluye el impulso de un régimen retributivo específico como función de coordinación.'}},
{n:9, q:'En el ámbito de la Comunitat Valenciana, según lo dispuesto en el art.4 de la Ley 17/2017, las funciones de coordinación se ejercerán por:', o:{a:'El Consell y la Agencia Valenciana de Seguridad y respuesta a las Emergencias (AVSRE).',b:'La Comisión de Coordinación de Policías Locales de la Comunitat Valenciana.',c:'Los consejos supramunicipales de coordinación de Policías Locales.',d:'Todos los citados en las respuestas anteriores.'}, correct:'d', why:{d:'El art.4 de la Ley 17/2017 establece que las funciones de coordinación se ejercerán por el Consell, la AVSRE, la Comisión de Coordinación de Policías Locales y los consejos supramunicipales.'}},
{n:10, q:'Según lo dispuesto en el art.5 de la Ley 17/2017:', o:{a:'Corresponde al Consell la potestad reglamentaria en materia de coordinación de policías locales en la Comunitat Valenciana.',b:'El ejercicio de las funciones de coordinación de las policías locales que no supongan el ejercicio de la potestad reglamentaria corresponderá al órgano autonómico competente en materia de seguridad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.5 Ley 17/2017 establece ambas previsiones: la potestad reglamentaria al Consell y el ejercicio de funciones no reglamentarias al órgano autonómico competente en seguridad.'}},
{n:11, q:'La AVSRE se crea mediante:', o:{a:'La Ley 4/2017, de 3 de febrero, de la Generalitat.',b:'La Ley 14/2018, de 13 de marzo, de la Generalitat.',c:'El Decreto 4/2017, de 3 de febrero, del Consell.',d:'El Decreto 14/2018, de 13 de marzo, del Consell.'}, correct:'a', why:{a:'La AVSRE fue creada por la Ley 4/2017, de 3 de febrero, de la Generalitat Valenciana, como organismo autónomo.'}},
{n:12, q:'La AVSRE está regulada:', o:{a:'En la Ley 4/2017, de la Generalitat, por la que se crea, y en el Decreto 122/2017 del Consell, por el que se aprueba su Reglamento Orgánico y Funcional.',b:'En la Ley 14/2018, de la Generalitat, por la que se crea, y en el Decreto 122/2018, del Consell, por el que se aprueba su Reglamento Orgánico y funcional.',c:'En el Decreto 4/2017, del Consell, por el que se crea, y en la Orden de 3 de febrero de 2017.',d:'En el Decreto 14/2018, del Consell, por el que se crea, y en la Orden de 13 de marzo de 2018.'}, correct:'a', why:{a:'La AVSRE se regula en la Ley 4/2017 de la Generalitat y su ROF fue aprobado por el Decreto 122/2017 del Consell.'}},
{n:13, q:'El Reglamento Orgánico y Funcional de la AVSRE ha sido objeto de modificación por medio de:', o:{a:'La Orden 122/2023, de 23 de noviembre, de la Consellería de Justicia e Interior.',b:'Los Decretos 83/2021 y 57/2024.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El ROF de la AVSRE aprobado por D.122/2017 fue modificado mediante los Decretos 83/2021 y 57/2024 del Consell.'}},
{n:14, q:'La AVSRE:', o:{a:'Es un organismo autónomo al que se le encomienda, en régimen de descentralización funcional, la ejecución de las políticas de la Generalitat en materia de interior, seguridad pública, protección ciudadana, la coordinación de policías locales y la formación de sus miembros.',b:'Está adscrita a la Consellería competente en materia de seguridad y gestión de emergencias a través de la Secretaría Autonómica con atribuciones en estas materias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Conforme a la Ley 4/2017, la AVSRE es un organismo autónomo adscrito a la Consellería competente en seguridad y emergencias a través de la Secretaría Autonómica.'}},
{n:15, q:'Según el art.3 de la Ley 4/2017, la AVSRE:', o:{a:'Tiene por finalidad dar una respuesta eficaz y eficiente, posibilitando una mejor y más ágil gestión de los recursos y una mayor participación y asunción de responsabilidades.',b:'Tiene por finalidad dar una respuesta eficaz y eficiente, posibilitando la oferta de soluciones ante situaciones de emergencia y situaciones que atenten contra la seguridad de personas y bienes.',c:'Tiene por finalidad lograr una mayor participación de la sociedad y una modernización del sistema público de respuesta a las emergencias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.3 Ley 4/2017 recoge como finalidad de la AVSRE todos los objetivos citados.'}},
{n:16, q:'El art.3 de la Ley 4/2017 describe los objetivos específicos que corresponden a la AVSRE. Indique cual de los siguientes es incorrecto:', o:{a:'La coordinación de las policías locales entendida como la determinación de los criterios necesarios para la mejor adecuación de la formación, organización, dotación y actuación de las policías locales.',b:'La dirección y gestión de la encomienda hecha por el Consejo de Seguridad Nuclear del Estado.',c:'La dirección y gestión de las políticas relacionadas con la formación y selección de policías locales y de los servicios de bomberos.',d:'La dirección y gestión de la participación de la Generalitat en los consorcios provinciales de bomberos.'}, correct:'b', why:{b:'La dirección y gestión de la encomienda del Consejo de Seguridad Nuclear no es un objetivo del art.3 Ley 4/2017; está contemplado como función en el art.4 y regulado en el art.10.'}},
{n:17, q:'El art.3 de la Ley 4/2017 dispone que la efectiva dirección y gestión de las políticas de la Generalitat en materia de protección civil y emergencias y extinción de incendios forestales, es un objetivo de la AVSRE, según lo establecido:', o:{a:'En la Ley 13/2010, de 23 de noviembre, de la Generalitat, de protección civil y gestión de emergencias.',b:'En la Ley 3/1993, de 9 de diciembre, de la Generalitat, forestal de la Comunitat Valenciana.',c:'En la Ley 7/2011, de 1 de abril, de la Generalitat, de los servicios de prevención, extinción de incendios y salvamento de la Comunitat Valenciana.',d:'En toda la normativa citada en las respuestas anteriores.'}, correct:'d', why:{d:'El art.3 Ley 4/2017 remite a toda la normativa citada: Ley 13/2010, Ley 3/1993 forestal y Ley 7/2011 de bomberos.'}},
{n:18, q:'La dirección y gestión de la encomienda hecha por el Consejo de Seguridad Nuclear a la Generalitat:', o:{a:'Es uno de los objetivos de la AVSRE.',b:'Está regulada en el art.10 de la Ley 4/2017.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Según el art.3 Ley 4/2017, la dirección y gestión de la encomienda del Consejo de Seguridad Nuclear es uno de los objetivos específicos de la AVSRE.'}},
{n:19, q:'El art.3 de la Ley 4/2017 describe los objetivos específicos que corresponden a la AVSRE. Indique cual de los siguientes es incorrecto:', o:{a:'La dirección y gestión de la encomienda hecha por el Consejo de Seguridad Nuclear del Estado.',b:'El análisis de la vulnerabilidad del territorio de la Comunitat Valenciana para la elaboración de los distintos mapas de riesgos.',c:'El incremento de la prevención de las situaciones de riesgo y la disminución de sus consecuencias.',d:'El fomento de la promoción de la autoprotección mediante la información y sensibilización necesaria de los ciudadanos, empresas e instituciones.'}, correct:'a', why:{a:'La dirección y gestión de la encomienda del Consejo de Seguridad Nuclear no figura entre los objetivos específicos del art.3 Ley 4/2017; es una función del art.4.'}},
{n:20, q:'El art.3 de la Ley 4/2017 describe los objetivos específicos que corresponden a la AVSRE. Indique cual de los siguientes es incorrecto:', o:{a:'La eficaz planificación de la respuesta frente a siniestros producidos o previsibles, mediante planes de protección civil.',b:'El establecimiento de la estructura de coordinación, las comunicaciones, el sistema de mando y el control general de los distintos órganos e instituciones implicados.',c:'La calidad e inmediata recepción y la gestión de las llamadas de emergencia de los ciudadanos a través del 112 Comunitat Valenciana.',d:'La eficiente intervención para paliar y corregir las causas y minimizar los efectos de las situaciones de emergencias.'}, correct:'b', why:{b:'El establecimiento de la estructura de coordinación y sistema de mando no figura entre los objetivos específicos del art.3 Ley 4/2017 para la AVSRE.'}},
{n:21, q:'El art.3 de la Ley 4/2017 establece los objetivos específicos que corresponden a la AVSRE. Indique cual de los siguientes es incorrecto:', o:{a:'La procedente coordinación de la rehabilitación de las zonas afectadas por las emergencias y la gestión de la vuelta a la normalidad.',b:'El establecimiento de la estructura de coordinación, las comunicaciones, el sistema de mando y el control general de los distintos órganos e instituciones implicados.',c:'La garantía de la formación adecuada de las personas que pertenecen a los servicios de intervención y el establecimiento de las dotaciones mínimas de medios materiales.',d:'El incremento de la coordinación de los diferentes servicios de intervención en emergencias y velar la implementación de medidas en seguridad y salud en el trabajo.'}, correct:'b', why:{b:'El establecimiento de la estructura de coordinación y sistema de mando no figura entre los objetivos específicos del art.3 Ley 4/2017 para la AVSRE.'}},
{n:22, q:'El art.3 de la Ley 4/2017 establece los objetivos específicos que corresponden a la AVSRE. Indique cual de los siguientes es incorrecto:', o:{a:'La suficiente coordinación o transmisión de información en materia de emergencias, según los planes de actuación establecidos al efecto.',b:'Estudiar el diseño de una policía autónoma valenciana dependiente del Consell.',c:'El establecimiento de la estructura de coordinación, las comunicaciones, el sistema de mando y el control común de los distintos órganos y entidades que actúan en respuesta a la emergencia.',d:'La formación continua y transversal de todo el personal dependiente de la Generalitat que tenga atribuida competencias en materia de seguridad.'}, correct:'d', why:{d:'La formación continua y transversal de todo el personal dependiente de la Generalitat con competencias en seguridad no figura entre los objetivos específicos del art.3 Ley 4/2017 para la AVSRE.'}},
{n:23, q:'En relación con la Unidad del Cuerpo Nacional de Policía Adscrita a la Comunitat Valenciana, la AVSRE tiene como objetivo:', o:{a:'La dirección y gestión derivadas de la Ley orgánica 2/1986, de 13 de marzo, de fuerzas y cuerpos de seguridad.',b:'El acuerdo administrativo de colaboración entre el Ministerio del Interior y la Generalitat en materia policial.',c:'El ejercicio de las competencias en materia de personal y operativa de los miembros de dicha unidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.3 Ley 4/2017 contempla como objetivo de la AVSRE respecto a la Unidad CNP adscrita, todos los aspectos citados.'}},
{n:24, q:'El art.4 de la Ley 4/2017 describe cuales son las funciones que corresponden a la AVSRE. Indique cual de las siguientes es incorrecta:', o:{a:'Desarrollar y coordinar la política y los programas en materia de protección civil y gestión de emergencias según las directrices emanadas del Consell.',b:'Gestionar los expedientes de concesión de distinciones de la Generalitat en materia de seguridad y emergencias, cuando proceda según lo previsto en la legislación vigente.',c:'Elaborar el Plan territorial de emergencia de la Comunitat Valenciana y los planes especiales.',d:'Gestionar la participación necesaria y obligatoria de entidades públicas o privadas y particulares, cuando proceda, para el cumplimiento de las obligaciones establecidas en la normativa vigente.'}, correct:'b', why:{b:'La gestión de expedientes de concesión de distinciones en materia de seguridad y emergencias no figura entre las funciones del art.4 Ley 4/2017 en los términos de esa opción.'}},
{n:25, q:'El art.4 de la Ley 4/2017 describe cuales son las funciones que corresponden a la AVSRE. Indique cual de las siguientes es incorrecta:', o:{a:'Gestionar la participación necesaria y obligatoria de entidades públicas o privadas y particulares, cuando proceda, para el cumplimiento de las obligaciones establecidas en la normativa vigente.',b:'Gestionar el Registro autonómico de planes de autoprotección.',c:'Gestionar los Registros de Bomberos y de los Servicios de Voluntariado de Protección Civil de la Comunitat Valenciana.',d:'Gestionar los expedientes de concesión de distinciones de la Generalitat en materia de protección civil.'}, correct:'a', why:{a:'La participación en los términos de esa opción no corresponde a la AVSRE según el art.4 Ley 4/2017.'}},
{n:26, q:'El art.4 de la Ley 4/2017 describe cuales son las funciones que corresponden a la AVSRE. Indique cual de las siguientes es incorrecta:', o:{a:'Gestionar la extinción de los incendios forestales, cuando no esté atribuida a otra administración.',b:'Requerir de las restantes administraciones públicas, entidades públicas o privadas y particulares la colaboración necesaria.',c:'Establecer los medios para fomentar actuaciones que contribuyan a la prevención de siniestros.',d:'Gestionar el Centro de Coordinación de Emergencias.'}, correct:'a', why:{a:'Gestionar la extinción de incendios forestales cuando no esté atribuida a otra administración no figura en el art.4 Ley 4/2017 como función directa de la AVSRE.'}},
{n:27, q:'El art.4 de la Ley 4/2017 describe cuales son las funciones que corresponden a la AVSRE. Indique cual de las siguientes es incorrecta:', o:{a:'Coordinar entre sí los servicios públicos o privados que deban intervenir en situaciones de emergencia.',b:'Disponer de los mapas de riesgos y elaborar el catálogo de recursos de emergencia y de actividades con riesgo de la Comunitat Valenciana.',c:'Ejercer la potestad sancionadora, en los términos establecidos en la Ley 23/2015.',d:'Gestionar la extinción de los incendios forestales.'}, correct:'c', why:{c:'La potestad sancionadora de la AVSRE se ejerce en los términos de la Ley 13/2010, no de la Ley 23/2015, según el art.4 Ley 4/2017.'}},
{n:28, q:'El art.4 de la Ley 4/2017 describe cuales son las funciones que corresponden a la AVSRE. Indique cual de las siguientes es incorrecta:', o:{a:'Promocionar y apoyar la vinculación voluntaria y desinteresada de los ciudadanos a las actividades de protección civil.',b:'Ejercer la potestad sancionadora, en los términos establecidos en la Ley 13/2010.',c:'Impulsar y coordinar las actuaciones de las diferentes administraciones para la vuelta de la normalidad tras una situación de emergencia declarada.',d:'Elaborar informes vinculantes para la aprobación de los planes de emergencia de carácter estatal autonómico y local.'}, correct:'d', why:{d:'La AVSRE no elabora informes vinculantes para la aprobación de planes estatales de emergencia en esos términos según el art.4 Ley 4/2017.'}},
{n:29, q:'El art.4 de la Ley 4/2017 describe cuales son las funciones que corresponden a la AVSRE. Indique cual de las siguientes es incorrecta:', o:{a:'Intervenir operativamente en caso de grave riesgo, catástrofe o calamidad pública, así como en emergencias menores.',b:'Gestionar la extinción de los incendios forestales, cuando no esté atribuida a otra administración.',c:'Participar en los planes de emergencia de carácter estatal y local.',d:'Apoyar a los distintos servicios o entidades que intervengan en casos de emergencia.'}, correct:'b', why:{b:'Gestionar la extinción de incendios forestales cuando no esté atribuida a otra administración no es función directa de la AVSRE según el art.4 Ley 4/2017.'}},
{n:30, q:'El art.4 de la Ley 4/2017 describe cuales son las funciones que corresponden a la AVSRE. Indique cual de las siguientes es incorrecta:', o:{a:'Informar y formar en materia de protección civil a la población en general y a colectivos específicos afectados por los correspondientes planes.',b:'Llevar a cabo los estudios necesarios para la elaboración del Plan territorial de protección civil.',c:'Dirigir y gestionar las políticas de la Generalitat en materia de seguridad pública y seguridad ciudadana.',d:'Gestionar la extinción de los incendios forestales, cuando no esté atribuida a otra administración.'}, correct:'d', why:{d:'Gestionar la extinción de incendios forestales cuando no esté atribuida a otra administración no figura entre las funciones del art.4 Ley 4/2017.'}},
{n:31, q:'El art.4 de la Ley 4/2017 describe cuales son las funciones que corresponden a la AVSRE. Indique cual de las siguientes es incorrecta:', o:{a:'Gestionar el Registro de Policías Locales de la Comunitat Valenciana y el que se fije para el personal de los servicios de prevención, extinción de incendios y salvamento.',b:'Proponer y elaborar el estudio, asesoramiento y desarrollo normativo apropiado tanto en materia de policía local como del personal de los servicios de prevención, extinción de incendios y salvamento.',c:'Gestionar la extinción de los incendios forestales, cuando no esté atribuida a otra administración.',d:'Prestar información y asesoramiento jurídico y técnico en las materias que les son propias a los cuerpos de policía local.'}, correct:'c', why:{c:'Gestionar la extinción de incendios forestales cuando no esté atribuida a otra administración no es función de la AVSRE según el art.4 Ley 4/2017.'}},
{n:32, q:'La AVSRE gestionará los expedientes de concesión de reconocimiento, distinciones y condecoraciones al mérito:', o:{a:'De los cuerpos de policía local.',b:'De los servicios de prevención, extinción de incendios y salvamento.',c:'De los agentes medioambientales.',d:'De todos los citados en las respuestas anteriores.'}, correct:'d', why:{d:'Conforme al art.4 Ley 4/2017, la AVSRE gestiona los expedientes de distinciones de los cuerpos de policía local, bomberos y agentes medioambientales.'}},
{n:33, q:'La ejecución de las funciones reguladas en el art.4 de la Ley 4/2017, mas aquellas otras que le atribuya la normativa vigente a la AVSRE, las realizará:', o:{a:'En coordinación con las demás administraciones públicas y previa supervisión de los órganos estatales competentes.',b:'En el marco de la política de prevención de riesgos adoptada por los órganos administrativos de la Generalitat competentes por razón de la materia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Según el art.4 in fine Ley 4/2017, la AVSRE ejercerá sus funciones en el marco de la política de prevención de riesgos adoptada por los órganos de la Generalitat competentes.'}},
{n:34, q:'Según lo dispuesto en el art.5 de la Ley 4/2017, los órganos de la AVSRE pueden ser:', o:{a:'Directivos, de participación o adscritos.',b:'Directivos, ejecutivos y de participación.',c:'Ejecutivos, directivos, participativos o adscritos a la misma.',d:'Ejecutivos, participativos, adscritos o de representación.'}, correct:'a', why:{a:'El art.5 Ley 4/2017 clasifica los órganos de la AVSRE en: directivos, de participación y adscritos.'}},
{n:35, q:'El art.5 de la Ley 4/2017 describe cuales son los órganos directivos de la AVSRE. Indique cual de los siguientes no es uno de ellos:', o:{a:'El Consejo de Dirección de la AVSRE.',b:'La Presidencia de la AVSRE.',c:'La Dirección de la AVSRE.',d:'La Comisión de Coordinación de Policías Locales de la Comunitat Valenciana.'}, correct:'d', why:{d:'La Comisión de Coordinación de Policías Locales es un órgano de participación adscrito a la AVSRE (art.5 Ley 4/2017), no un órgano directivo.'}},
{n:36, q:'El art.5 de la Ley 4/2017 establece cuales son los órganos de participación adscritos a la AVSRE. Indique cual de los siguientes no es uno de ellos:', o:{a:'La Comisión de Protección Civil y Emergencias de la Comunitat Valenciana.',b:'El Gabinete Técnico de Coordinación de Policías Locales de la Comunitat Valenciana.',c:'La Mesa Sectorial de Protección Civil y Emergencias de la Comunitat Valenciana.',d:'La Comisión de Coordinación de los Servicios de Prevención y Extinción de Incendios y Salvamento de la Comunitat Valenciana.'}, correct:'b', why:{b:'El Gabinete Técnico de Coordinación de Policías Locales no es un órgano de participación adscrito a la AVSRE según el art.5 Ley 4/2017.'}},
{n:37, q:'El art.5 de la Ley 4/2017 establece cuales son los órganos de participación adscritos a la AVSRE, siendo uno de ellos:', o:{a:'El Observatorio de la Seguridad de la Comunitat Valenciana.',b:'El Gabinete Técnico de Coordinación de Policías Locales de la Comunitat Valenciana.',c:'El Instituto Valenciano de Seguridad Pública y Emergencias (IVASPE).',d:'El Centro de Coordinación de Emergencias de la Comunitat Valenciana.'}, correct:'a', why:{a:'El Observatorio de la Seguridad de la Comunitat Valenciana es uno de los órganos de participación adscritos a la AVSRE según el art.5 Ley 4/2017.'}},
{n:38, q:'El art.5 de la Ley 4/2017 establece cuales son los órganos de participación adscritos a la AVSRE, siendo uno de ellos:', o:{a:'El Gabinete Técnico de Coordinación de Policías Locales de la Comunitat Valenciana.',b:'El Centro de Coordinación de Emergencias de la Comunitat Valenciana.',c:'La Comisión de Coordinación de Policías Locales de la Comunitat Valenciana.',d:'Son todos los citados en las respuestas anteriores.'}, correct:'c', why:{c:'La Comisión de Coordinación de Policías Locales de la Comunitat Valenciana es uno de los órganos de participación adscritos a la AVSRE (art.5 Ley 4/2017).'}},
{n:39, q:'El art.5 de la Ley 4/2017 establece cuales son los órganos adscritos a la AVSRE. Indique cual de los siguientes no es uno de ellos:', o:{a:'El Instituto Valenciano de Seguridad Pública y Emergencias (IVASPE).',b:'La Mesa Sectorial de Protección Civil y Emergencias de la Comunitat Valenciana.',c:'El Gabinete Técnico de Coordinación de Policías Locales de la Comunitat Valenciana.',d:'El Centro de Coordinación de Emergencias de la Comunitat Valenciana.'}, correct:'b', why:{b:'La Mesa Sectorial de Protección Civil y Emergencias es un órgano de participación adscrito, no un órgano adscrito en sentido estricto según el art.5 Ley 4/2017.'}},
{n:40, q:'El art.5 de la Ley 4/2017 establece cuales son los órganos adscritos a la AVSRE. Indique cual de los siguientes no es uno de ellos:', o:{a:'La Mesa Sectorial de Protección Civil y Emergencias de la Comunitat Valenciana.',b:'El Centro de Coordinación de Emergencias de la Comunitat Valenciana.',c:'El Servicio de Bomberos Forestales.',d:'La Oficina Única Postemergencia.'}, correct:'a', why:{a:'La Mesa Sectorial de Protección Civil y Emergencias es un órgano de participación adscrito, no un órgano adscrito del art.5 Ley 4/2017.'}},
{n:41, q:'La Disposición Adicional 4ª de la Ley 17/2017 adscribe a la AVSRE:', o:{a:'A los Consejos Supramunicipales de Coordinación de Policías Locales.',b:'Al Comité de Ética y Transparencia de la Actividad Policial.',c:'Al Comité de Asuntos Internos.',d:'A todos los citados en las respuestas anteriores.'}, correct:'d', why:{d:'La Disposición Adicional 4ª de la Ley 17/2017 adscribe a la AVSRE los Consejos Supramunicipales, el Comité de Ética y Transparencia y el Comité de Asuntos Internos.'}},
{n:42, q:'El D.122/2017 establece cuales son los órganos de la AVSRE:', o:{a:'En su Título I.',b:'En su Título II.',c:'En su Título III.',d:'En su Título IV.'}, correct:'c', why:{c:'El Decreto 122/2017 (ROF de la AVSRE) regula los órganos de la AVSRE en su Título III.'}},
{n:43, q:'Con respecto a los órganos de la AVSRE, el art.19.3 del D.122/2017 establece que:', o:{a:'La composición, funcionamiento, objetivos y funciones de los órganos directivos será el establecido en este decreto.',b:'El régimen de funcionamiento, composición y funciones de los órganos adscritos a la AVSRE será el establecido en la normativa reguladora de cada órgano.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.19.3 del D.122/2017 establece que el régimen de los órganos adscritos a la AVSRE se regirá por su propia normativa reguladora.'}},
{n:44, q:'El Consejo de Dirección de la AVSRE está formado por:', o:{a:'La Presidencia, dos vicepresidencias y 20 vocales.',b:'La Presidencia, dos vicepresidencias y 12 vocales.',c:'La Presidencia, dos vicepresidencias y 10 vocales.',d:'La Presidencia, una vicepresidencia y 10 vocales.'}, correct:'a', why:{a:'Conforme al art.20 D.122/2017, el Consejo de Dirección de la AVSRE está integrado por la Presidencia, dos Vicepresidencias y 20 vocales.'}},
{n:45, q:'Con respecto a los órganos de la AVSRE, el Título III del D.122/2017 regula:', o:{a:'En su Capítulo II los Órganos Directivos.',b:'En su Capítulo IV los Órganos de Participación.',c:'En su Capítulo V los Órganos Adscritos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El Título III del D.122/2017 dedica el Cap.II a órganos directivos, Cap.IV a órganos de participación y Cap.V a órganos adscritos.'}},
{n:46, q:'La Presidencia del Consejo de Dirección y de la AVSRE corresponde:', o:{a:'Al Conseller/a competente en materia de seguridad y emergencias.',b:'Al Conseller/a competente en materia de medio ambiente.',c:'Al titular de la Secretaria Autonómica competente en materia de seguridad y emergencias.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'Conforme al art.21 D.122/2017, la Presidencia del Consejo de Dirección y de la AVSRE corresponde al Conseller/a competente en materia de seguridad y emergencias.'}},
{n:47, q:'La Vicepresidencia I del Consejo de dirección de la AVSRE corresponde:', o:{a:'Al Conseller/a competente en materia de seguridad y emergencias.',b:'Al Conseller/a competente en materia de medio ambiente.',c:'Al titular de la Secretaria Autonómica competente en materia de seguridad y emergencias.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'Conforme al D.122/2017, la Vicepresidencia I del Consejo de Dirección corresponde al Conseller/a competente en materia de medio ambiente.'}},
{n:48, q:'La Vicepresidencia II del Consejo de Dirección de la AVSRE corresponde:', o:{a:'Al Conseller/a competente en materia de seguridad y emergencias.',b:'Al Conseller/a competente en materia de medio ambiente.',c:'Al titular de la Secretaria Autonómica competente en materia de seguridad y emergencias.',d:'En el Consejo de dirección de la AVSRE solo hay una Vicepresidencia.'}, correct:'c', why:{c:'La Vicepresidencia II del Consejo de Dirección de la AVSRE corresponde al titular de la Secretaría Autonómica competente en materia de seguridad y emergencias (D.122/2017).'}},
{n:49, q:'El art.6 de la Ley 4/2017 establece que en el seno del Consejo de Dirección de la AVSRE se constituirá una Comisión Permanente y describe quienes serán sus miembros. Indique cual de los siguientes no es uno de ellos:', o:{a:'La persona que ostente la Presidencia de la AVSRE.',b:'La persona que ostente la dirección de la AVSRE, que será el/la titular de la secretaría autonómica con competencias en materia de seguridad y emergencias.',c:'La persona titular de la Secretaria Autonómica con competencia en materia de medio ambiente.',d:'La persona titular de la Subsecretaría de la Consellería competente en materia de seguridad y emergencias.'}, correct:'c', why:{c:'La persona titular de la Secretaría Autonómica de medio ambiente no forma parte de la Comisión Permanente del Consejo de Dirección según el art.6 Ley 4/2017.'}},
{n:50, q:'El art.6 de la Ley 4/2017 establece que en el seno del Consejo de Dirección de la AVSRE se constituirá una Comisión Permanente y describe quienes serán sus miembros. Indique cual de los siguientes no es uno de ellos:', o:{a:'Un representante, con rango de al menos director/a general de la Consellería competente en materia de prevención de incendios forestales.',b:'La persona titular de la Subsecretaría de la Consellería competente en materia de medio ambiente.',c:'La persona que ostente la Jefatura de la Unidad adscrita del Cuerpo Nacional de Policía en la Comunitat Valenciana.',d:'Un representante de los diputados/as delegados/as de los Consorcios Provinciales de Bomberos.'}, correct:'b', why:{b:'La persona titular de la Subsecretaría de la Consellería de medio ambiente no figura entre los miembros de la Comisión Permanente del Consejo de Dirección según el art.6 Ley 4/2017.'}},
{n:51, q:'Con respecto a la Secretaría del Consejo de Dirección de la AVSRE, tanto del Pleno como de la Comisión Permanente, el art.6 de la Ley 4/2017 dispone que quien la ejerza:', o:{a:'Deberá ser funcionario/a de la AVSRE, integrado/a en el grupo A1.',b:'Deberá tener licenciatura o grado en Derecho.',c:'Asistirá a las reuniones con voz pero sin voto.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.6 Ley 4/2017 establece que el Secretario/a del Consejo de Dirección será funcionario/a grupo A1, con licenciatura en Derecho y asistirá con voz pero sin voto.'}},
{n:52, q:'El art.7 de la Ley 4/2017 describe las funciones del Consejo de Dirección de la AVSRE. Indique cual de las siguientes no es correcta:', o:{a:'Aprobar las directrices generales de actuación del organismo autónomo, en el marco de las políticas públicas autonómicas.',b:'Informar las leyes que les afecten, así como emitir dictámenes e informar sobre materias que puedan suscitar controversia con otras administraciones.',c:'Aprobar los planes y programas de actuación del organismo para cada ejercicio, así como la memoria de actividades del ejercicio anterior.',d:'Ratificar las resoluciones y actuaciones que por urgencia hubiera tenido que adoptar la persona titular de la Dirección de la AVSRE.'}, correct:'b', why:{b:'Informar leyes y emitir dictámenes sobre controversias con otras administraciones no es función del Consejo de Dirección (art.7 Ley 4/2017); corresponde a la Comisión Permanente (art.8).'}},
{n:53, q:'Según el art.7 de la Ley 4/2017, al Consejo de Dirección de la AVSRE le corresponde:', o:{a:'Informar aquellas leyes que afecten a las funciones que la AVSRE tiene encomendadas en la presente ley y demás normativa que le sea de aplicación.',b:'Informar los asuntos que la Dirección de la AVSRE le someta a su consideración, así como cualesquiera otras funciones que se le atribuyan legal o reglamentariamente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.7 Ley 4/2017 atribuye al Consejo de Dirección informar las leyes que afecten a la AVSRE y los asuntos que la Dirección someta a su consideración.'}},
{n:54, q:'El art.8 de la Ley 4/2017 describe las funciones que corresponden a la Comisión Permanente del Consejo de Dirección de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Tratar de aquellos asuntos propios del pleno de la AVSRE que, por no admitir dilaciones, deban ser abordados en el período interplenario.',b:'Analizar los asuntos del Consejo de Dirección y elevar propuestas al Pleno del mismo.',c:'Informar los asuntos que la Dirección de la AVSRE le someta a su consideración.',d:'Colaborar con la Dirección de la AVSRE en el desarrollo de sus funciones.'}, correct:'c', why:{c:'Informar los asuntos que la Dirección someta a su consideración no figura entre las funciones de la Comisión Permanente (art.8 Ley 4/2017); es función del Consejo de Dirección (art.7).'}},
{n:55, q:'El art.8 de la Ley 4/2017 describe las funciones que corresponden a la Comisión Permanente del Consejo de Dirección de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Resolver las dudas de procedimiento y organización que puedan surgir en el funcionamiento de la AVSRE.',b:'Emitir dictámenes e informar sobre materias que puedan suscitar controversia con organismos de otras administraciones.',c:'Llevar a cabo todas las funciones que le delegue o encomiende el Pleno del Consejo de Dirección de la AVSRE.',d:'Colaborar con la Dirección de la AVSRE en el desarrollo de sus funciones.'}, correct:'b', why:{b:'Emitir dictámenes sobre controversias con otras administraciones no es función de la Comisión Permanente según el art.8 Ley 4/2017.'}},
{n:56, q:'Según lo establecido en la Ley 4/2017, respecto al Consejo de Dirección de la AVSRE, indique la afirmación incorrecta:', o:{a:'Es el órgano colegiado de control, planificación y supervisión general de la actividad del organismo.',b:'Ejerce el control y supervisión de las funciones directivas del organismo.',c:'Podrá actuar en pleno o en Comisión Permanente.',d:'En caso de ausencia de la persona titular de la Presidencia, corresponderá presidir el Pleno del Consejo a la Vicepresidencia I.'}, correct:'d', why:{d:'Según el art.6 Ley 4/2017, en ausencia de la Presidencia corresponde presidir el Pleno a la Vicepresidencia II, no a la I.'}},
{n:57, q:'Respecto al Consejo de Dirección de la AVSRE, según lo establecido en la Ley 4/2017:', o:{a:'En caso de ausencia de la persona titular de la Presidencia, corresponderá presidir el Pleno del Consejo a la Vicepresidencia II.',b:'El Pleno está integrado por la Presidencia, las vicepresidencias I y II y todas las vocalías del Consejo de Dirección.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Conforme al art.6 Ley 4/2017, en ausencia de la Presidencia preside la Vicepresidencia II y el Pleno está integrado por Presidencia, vicepresidencias y todas las vocalías.'}},
{n:58, q:'Según lo establecido en la Ley 4/2017, el Pleno del Consejo de Dirección de la AVSRE se reunirá:', o:{a:'Como mínimo una vez cada seis meses.',b:'Siempre que sea convocado por la persona titular de su Presidencia.',c:'Cuando sea solicitado por una tercera parte de sus miembros.',d:'Todas la respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.6 Ley 4/2017 establece que el Pleno se reúne al menos cada seis meses, cuando lo convoque la Presidencia y cuando lo solicite un tercio de sus miembros.'}},
{n:59, q:'Según lo establecido en la Ley 4/2017, la Comisión Permanente del Consejo de Dirección de la AVSRE:', o:{a:'Se reunirá siempre que resulte necesario para el adecuado ejercicio de sus funciones, a convocatoria de la persona que ostente la Presidencia de la AVSRE, que la presidirá.',b:'Debe obtener la mayoría de dos tercios de sus miembros para adoptar acuerdos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.6 Ley 4/2017 establece que la Comisión Permanente se reúne cuando resulte necesario, convocada y presidida por la persona titular de la Presidencia de la AVSRE.'}},
{n:60, q:'Según lo establecido en el art.9 de la Ley 4/2017, la Comisión Permanente del Consejo de Dirección de la AVSRE se reunirá:', o:{a:'Cuando sea requerida por un tercio de sus miembros.',b:'Cuando sea requerida por, al menos, dos de sus miembros.',c:'Cuando sea requerida por, al menos, tres de sus miembros.',d:'Cuando sea requerida por más de uno de sus miembros.'}, correct:'b', why:{b:'El art.9 Ley 4/2017 establece que la Comisión Permanente se reunirá cuando sea requerida por al menos dos de sus miembros.'}},
{n:61, q:'Según lo establecido en el art.10 de la Ley 4/2017, la dirección de la AVSRE la ostentará:', o:{a:'La persona titular de la secretaría autonómica con competencias en materia de medio ambiente, seguridad y emergencias.',b:'El/la Secretario/a Autonómico/a competente en materia de seguridad y repuesta a las emergencias.',c:'El/la Secretario/a Autonómico/a competente en materia de medio ambiente o de seguridad y emergencias.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art.10 Ley 4/2017 atribuye la dirección de la AVSRE al/la Secretario/a Autonómico/a competente en materia de seguridad y respuesta a las emergencias.'}},
{n:62, q:'El art.11 de la Ley 4/2017 describe las atribuciones que corresponden a la persona titular de la Presidencia de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'La representación institucional de la Agencia.',b:'La firma de los convenios en materias que sean competencia de la Agencia.',c:'Ejercer las facultades ordinarias y extraordinarias que se presenten en materia de contratación y gestión económica.',d:'Aprobar las encomiendas de gestión que sean necesarias para el cumplimiento de los fines de la AVSRE, cuyo importe sea inferior a diez millones de euros.'}, correct:'c', why:{c:'Ejercer las facultades ordinarias y extraordinarias en materia de contratación y gestión económica corresponde a la Dirección, no a la Presidencia (art.11 Ley 4/2017).'}},
{n:63, q:'El art.11 de la Ley 4/2017 describe las atribuciones que corresponden a la persona titular de la Presidencia de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Aprobar modificaciones en la regulación normativa de la Agencia.',b:'Ejercer las facultades ordinarias en materia de contratación.',c:'Proponer las convocatorias públicas y el nombramiento del personal para la provisión de puestos por libre designación.',d:'Otorgar reconocimientos y felicitaciones en materia de protección civil, atención de emergencias y seguridad, conforme a la normativa vigente.'}, correct:'a', why:{a:'Aprobar modificaciones en la regulación normativa de la Agencia corresponde a la Dirección de la AVSRE, no a la Presidencia (art.11 Ley 4/2017).'}},
{n:64, q:'El art.11 de la Ley 4/2017 describe las atribuciones que corresponden a la persona titular de la Presidencia de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Proponer al órgano competente de la Generalitat, la adquisición o la disposición de bienes inmuebles que puedan ser afectos o adscritos a la AVSRE.',b:'Proponer modificaciones en la regulación normativa de la Agencia.',c:'Aprobar anualmente la propuesta de anteproyecto de presupuestos del organismo autónomo.',d:'Ejercer las facultades ordinarias y extraordinarias que se presenten en materia de contratación y gestión económica.'}, correct:'d', why:{d:'Ejercer las facultades ordinarias y extraordinarias en materia de contratación y gestión económica no corresponde a la Presidencia sino a la Dirección (art.11 Ley 4/2017).'}},
{n:65, q:'Además de cualesquiera otras funciones que se le atribuyan reglamentariamente, a la persona titular de la Presidencia de la AVSRE le corresponde:', o:{a:'Proponer la aprobación, en su caso, de las tasas y precios públicos de las actividades que tiene que realizar la AVSRE.',b:'Ejercer las facultades ordinarias y extraordinarias que se presenten en materia de contratación y gestión económica.',c:'Aprobar modificaciones en la regulación normativa de la Agencia.',d:'Le corresponden todas las funciones descritas en las respuestas anteriores.'}, correct:'a', why:{a:'Según el art.11 Ley 4/2017, entre las atribuciones adicionales de la Presidencia se incluye proponer las tasas y precios públicos de actividades de la AVSRE.'}},
{n:66, q:'Aprobar las encomiendas de gestión que sean necesarias para el cumplimiento de los fines de la AVSRE, cuyo importe sea superior a diez millones de euros, según el art.11 de la Ley 4/2017, corresponde:', o:{a:'A la persona titular de la Presidencia de la AVSRE.',b:'Al Consell.',c:'A la persona titular de la Dirección de la AVSRE.',d:'Al Consejo de Dirección de la AVSRE.'}, correct:'b', why:{b:'El art.11 Ley 4/2017 establece que las encomiendas de gestión superiores a diez millones de euros deben ser aprobadas por el Consell.'}},
{n:67, q:'Formular la propuesta de anteproyecto de presupuestos de gastos e ingresos de la AVSRE, según el art.11 de la Ley 4/2017, corresponde:', o:{a:'A la persona titular de la Presidencia de la AVSRE.',b:'Al Consell.',c:'A la persona titular de la Dirección de la AVSRE.',d:'Al Consejo de Dirección de la AVSRE.'}, correct:'c', why:{c:'El art.11 Ley 4/2017 atribuye a la Dirección de la AVSRE formular la propuesta de anteproyecto de presupuestos de gastos e ingresos.'}},
{n:68, q:'El art.11 de la Ley 4/2017 describe las atribuciones que corresponden a la persona titular de la Dirección de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Elaborar la memoria anual de la AVSRE y los programas de actuación de la misma.',b:'La responsabilidad ordinaria del funcionamiento de los servicios que integren la AVSRE, ejecutando y haciendo cumplir las instrucciones de la presidencia.',c:'Ejercer la jefatura del personal adscrito a la AVSRE, gestionando de forma integrada los recursos humanos, materiales y económicos.',d:'Aprobar las convocatorias de concursos para la provisión de jefaturas de unidad administrativa del organismo autónomo.'}, correct:'d', why:{d:'Aprobar convocatorias de concursos para jefaturas de unidad administrativa corresponde a la Presidencia, no a la Dirección (art.11 Ley 4/2017).'}},
{n:69, q:'Según el art.11 de la Ley 4/2017, a la persona titular de la Dirección de la AVSRE le corresponde:', o:{a:'Formular las propuestas en materia de relaciones de puestos de trabajo y oferta de empleo público de la AVSRE.',b:'Ejercer la función de representación ordinaria de la AVSRE, incluida la representación judicial y extrajudicial.',c:'Proponer las convocatorias de concursos para la provisión de jefaturas de unidad administrativa del organismo autónomo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.11 Ley 4/2017 atribuye a la Dirección todas las funciones citadas: relaciones de puestos de trabajo, representación ordinaria y propuesta de convocatorias de concursos.'}},
{n:70, q:'Además de cualesquiera otras funciones que se le atribuyan reglamentariamente, a la persona titular de la Dirección de la AVSRE le corresponde:', o:{a:'Proponer al órgano competente de la Generalitat, la adquisición o la disposición de bienes inmuebles que puedan ser afectos o adscritos a la AVSRE.',b:'Proponer modificaciones en la regulación normativa de la Agencia.',c:'La gestión económica y presupuestaria del presupuesto de la AVSRE, autorizando, disponiendo y reconociendo obligaciones económicas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.11 Ley 4/2017 asigna a la Dirección de la AVSRE proponer bienes inmuebles, proponer modificaciones normativas y gestionar el presupuesto.'}},
{n:71, q:'Según lo establecido en los artículos 11 y 12 de la Ley 4/2017:', o:{a:'En caso de ausencia, vacante o enfermedad de la persona titular de la Presidencia de la AVSRE, sus funciones las ejercerá la persona titular de la dirección de la Agencia.',b:'La persona titular de la Presidencia de la AVSRE comparecerá ante les Corts a petición propia o siempre que lo solicite algún grupo parlamentario.',c:'La Presidencia y la Dirección de la AVSRE podrán delegar el ejercicio de alguna de sus atribuciones en otros órganos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Los arts. 11 y 12 Ley 4/2017 recogen todas las afirmaciones: sustitución en ausencia, comparecencia ante les Corts y posibilidad de delegación de atribuciones.'}},
{n:72, q:'El art.11 de la Ley 4/2017 describe las atribuciones que corresponden a la persona titular de la Dirección de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Resolver las reclamaciones de responsabilidad patrimonial.',b:'Incoar expedientes disciplinarios por la comisión de faltas leves, graves y muy graves y ejercer la potestad disciplinaria salvo cuando la sanción sea la separación del servicio.',c:'Administrar el patrimonio que tenga adscrito a la AVSRE.',d:'Proponer al órgano competente de la Generalitat, la adquisición o la disposición de bienes inmuebles afectos o adscritos a la AVSRE.'}, correct:'d', why:{d:'Proponer al órgano competente la adquisición o disposición de bienes inmuebles como atribución directa del art.11 Ley 4/2017 corresponde a la Presidencia, no a la Dirección.'}},
{n:73, q:'El art.11 de la Ley 4/2017 describe las atribuciones que corresponden a la persona titular de la Dirección de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Velar por la mejora de los métodos de trabajo, por la introducción de las innovaciones tecnológicas aplicables y por la optimización de los ingresos y gastos.',b:'Proponer modificaciones en la regulación normativa de la Agencia.',c:'Ejecutar y hacer cumplir los acuerdos del Consejo de Dirección de la AVSRE.',d:'Adoptar las resoluciones y actuaciones que por motivos de urgencia sean necesarias, que deberán someterse a la ratificación del Consejo de Dirección.'}, correct:'b', why:{b:'Proponer modificaciones en la regulación normativa de la Agencia es atribución de la Presidencia, no de la Dirección (art.11 Ley 4/2017).'}},
{n:74, q:'Según el art.10 del D.122/2017, entre las unidades en las que se estructura el nivel administrativo de la AVSRE, se encuentra:', o:{a:'La Unidad del Cuerpo nacional de Policía adscrita a la Comunitat Valenciana.',b:'La Subdirección General de Seguridad y la Subdirección General de Formación en Seguridad Pública y Emergencias.',c:'La Subdirección General de Emergencias y la Secretaría Técnica.',d:'Todas las unidades citadas en las respuestas anteriores forman parte de dicho nivel administrativo.'}, correct:'d', why:{d:'El art.10 D.122/2017 estructura el nivel administrativo de la AVSRE incluyendo la Unidad CNP adscrita, las Subdirecciones Generales y la Secretaría Técnica.'}},
{n:75, q:'La Unidad del Cuerpo Nacional de Policía, adscrita a la Comunitat Valenciana:', o:{a:'Depende orgánicamente del Ministerio de Interior y funcionalmente de la AVSRE.',b:'Tiene a su cargo las funciones y atribuciones señaladas en el artículo 38.1 de la Ley Orgánica 2/1986, y contenidas en el Acuerdo de Colaboración suscrito con el Ministerio de Interior al amparo del Real Decreto 221/1991.',c:'Ejerce su mando, coordinación y control operativo a través de la jefatura de la unidad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Conforme al D.122/2017, la Unidad CNP adscrita depende orgánicamente del Ministerio de Interior y funcionalmente de la AVSRE, con las funciones del art.38.1 LO 2/1986 y mando a través de su jefatura.'}},
{n:76, q:'Bajo la supervisión de la persona titular de la dirección de la AVSRE, la Subdirección General de Seguridad tiene atribuida:', o:{a:'La coordinación de los servicios y unidades adscritas a la AVSRE.',b:'La coordinación externa con otras administraciones públicas.',c:'La representación de la AVSRE en las tareas que se le encomienden.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El D.122/2017 atribuye a la Subdirección General de Seguridad la coordinación interna, la externa y la representación de la AVSRE.'}},
{n:77, q:'El art.12 del D.122/2017 describe las funciones que, en particular, ejercerá la Subdirección General de Seguridad de la AVSRE. Indique cuál de las siguientes no es una de ellas:', o:{a:'La asistencia técnica, jurídica y administrativa de la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.',b:'La gestión y tramitación de los asuntos relativos al régimen de personal y medios de la citada Unidad.',c:'La formación continua y permanente del personal de la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.',d:'El ejercicio de las funciones de coordinación de los cuerpos de la policía local de la Comunitat Valenciana.'}, correct:'d', why:{d:'El ejercicio de las funciones de coordinación de los cuerpos de policía local no corresponde a la Subdirección General de Seguridad (art.12 D.122/2017).'}},
{n:78, q:'El art.12 del D.122/2017 describe las funciones que, en particular, ejercerá la Subdirección General de Seguridad de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'La coordinación de la investigación en materia de seguridad.',b:'La realización de actividades y campañas de divulgación e información de la prevención en materia de seguridad de carácter general y sectorial.',c:'El asesoramiento sobre lo concerniente a programas y planes generales de actuación en materia de seguridad.',d:'La formación continua y permanente del personal de la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.'}, correct:'d', why:{d:'La formación continua y permanente del personal de la Unidad CNP adscrita corresponde a la Subdirección General de Formación, no a la de Seguridad (art.12 D.122/2017).'}},
{n:79, q:'Para el cumplimiento de las funciones que tiene encomendadas, la Subdirección General de Seguridad de la AVSRE tendrá bajo su dependencia:', o:{a:'El servicio de Régimen Jurídico y el servicio de Gestión en Seguridad Pública.',b:'La Unidad del Cuerpo nacional de Policía adscrita a la Comunitat Valenciana.',c:'La Dirección General de Seguridad y Emergencias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art.12 D.122/2017 establece que bajo la dependencia de la Subdirección General de Seguridad están el Servicio de Régimen Jurídico y el Servicio de Gestión en Seguridad Pública.'}},
{n:80, q:'El art.13.1 del D.122/2017 describe las funciones que corresponden al servicio de Régimen Jurídico de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Informar las bases de las convocatorias de los procesos de selección y promoción de policías locales y proponer el nombramiento de vocales para los órganos técnicos de selección.',b:'Gestionar el Registro de Policías Locales.',c:'El asesoramiento jurídico en materia de policías locales a los ayuntamientos de la Comunitat Valenciana.',d:'Elaborar los informes preceptivos de cobertura de personal funcionario interino en los cuerpos de la policía local.'}, correct:'b', why:{b:'Gestionar el Registro de Policías Locales corresponde al Servicio de Gestión en Seguridad Pública, no al Servicio de Régimen Jurídico (art.13.2 D.122/2017).'}},
{n:81, q:'El art.13.1 del D.122/2017 describe las funciones que corresponden al servicio de Régimen Jurídico de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar la coordinación de los cuerpos de la policía local en la Comunitat Valenciana.',b:'Estudiar y elaborar la normativa en materia de policía local, así como la memoria anual de actividad de la policía local.',c:'Convocar y asistir técnicamente al Gabinete Técnico de Coordinación de Policías Locales de la Comunitat Valenciana.',d:'Convocar y asistir técnicamente a la Comisión de Coordinación de Policías Locales de la Comunitat Valenciana.'}, correct:'a', why:{a:'Gestionar la coordinación de los cuerpos de policía local corresponde al Servicio de Gestión en Seguridad Pública, no al Servicio de Régimen Jurídico (art.13.2 D.122/2017).'}},
{n:82, q:'El art.13.1 del D.122/2017 describe las funciones que corresponden al servicio de Régimen Jurídico de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Elaborar informes técnicos sobre los anteproyectos de disposiciones que se sometan a su consideración.',b:'Asistir técnica y administrativamente a la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.',c:'Impulsar y desarrollar los proyectos de iniciativas reglamentarias a tramitar en la Subdirección General de Seguridad.',d:'Cualquiera que se le encomiende en relación con las materias que le son propias.'}, correct:'b', why:{b:'Asistir técnica y administrativamente a la Unidad del CNP adscrita corresponde al Servicio de Gestión en Seguridad Pública (art.13.2 D.122/2017).'}},
{n:83, q:'El art.13.2 del D.122/2017 describe las funciones que corresponden al servicio de Gestión en Seguridad Pública de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar los expedientes de concesión de distinciones y condecoraciones al mérito policial de los cuerpos de la policía local y de la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.',b:'Asistir técnica y administrativamente a la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.',c:'Gestionar y tramitar los asuntos relativos al régimen de personal y medios de la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.',d:'Elaborar los informes preceptivos de cobertura de personal funcionario interino en los cuerpos de la policía local.'}, correct:'d', why:{d:'Elaborar los informes preceptivos de cobertura de personal funcionario interino corresponde al Servicio de Régimen Jurídico (art.13.1 D.122/2017).'}},
{n:84, q:'El art.13.2 del D.122/2017 describe las funciones que corresponden al servicio de Gestión en Seguridad Pública de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Elaborar y tramitar las propuestas de contratación necesarias para la gestión de la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.',b:'Impulsar y desarrollar los proyectos de iniciativas reglamentarias a tramitar en la Subdirección General de Seguridad.',c:'Tramitar los expedientes de concesión de ayudas a los ayuntamientos de la Comunitat Valenciana que dispongan de cuerpo de policía local.',d:'Gestionar la coordinación de los cuerpos de la policía local en la Comunitat Valenciana.'}, correct:'b', why:{b:'Impulsar y desarrollar proyectos de iniciativas reglamentarias en la Subdirección General de Seguridad corresponde al Servicio de Régimen Jurídico (art.13.1 D.122/2017).'}},
{n:85, q:'Además de cualquier otra función que se le encomiende en relación con las materias que le son propias, y según el art.13.2 del D.122/2017, al servicio de Gestión en Seguridad Pública de la AVSRE le corresponde:', o:{a:'Gestionar el Registro de Policías Locales.',b:'Coordinación de las aplicaciones informáticas que se implementen en el ámbito de la seguridad pública.',c:'Gestionar y tramitar las propuestas ciudadanas en el portal de la transparencia de la Generalitat (portal GVOberta).',d:'Le corresponden todas las funciones descritas en las respuestas anteriores.'}, correct:'d', why:{d:'El art.13.2 D.122/2017 atribuye al Servicio de Gestión en Seguridad Pública el Registro de Policías Locales, la coordinación de aplicaciones informáticas y la tramitación de propuestas ciudadanas del portal GVOberta.'}},
{n:86, q:'La Subdirección General de Formación en Seguridad Pública y Emergencias, bajo la supervisión de la persona titular de la Dirección de la AVSRE, tiene atribuida la coordinación de sus servicios y unidades.', o:{a:'Incorrecto.',b:'Correcto y, en particular, ejercerá las funciones descritas en el art.13.3 del D.122/2017.',c:'Correcto y, en particular, ejercerá las funciones descritas en el art.13 bis del D.122/2017.',d:'Correcto y, en particular, ejercerá las funciones descritas en el art.13 ter del D.122/2017.'}, correct:'c', why:{c:'La Subdirección General de Formación en Seguridad Pública y Emergencias ejerce las funciones descritas en el art.13 bis del D.122/2017.'}},
{n:87, q:'El art.13.bis del D.122/2017 describe las funciones que, en particular, ejercerá la Subdirección General de Formación en Seguridad Pública y Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Ejercer las funciones de coordinación para la formación de los cuerpos de la policía local de la Comunitat Valenciana.',b:'Gestionar el Instituto Valenciano de Seguridad Pública y Emergencias (IVASPE).',c:'Elaborar los informes preceptivos de cobertura de personal funcionario interino en los cuerpos de la policía local.',d:'Ejercer la dirección administrativa de la formación de policías locales, del personal de la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.'}, correct:'c', why:{c:'Elaborar los informes preceptivos de cobertura de personal funcionario interino corresponde al Servicio de Régimen Jurídico, no a la Subdirección General de Formación (art.13 bis D.122/2017).'}},
{n:88, q:'El art.13.bis del D.122/2017 describe las funciones que, en particular, ejercerá la Subdirección General de Formación en Seguridad Pública y Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Llevar a cabo la investigación, desarrollo e innovación en materia de seguridad a través del organismo que tiene asumidas las competencias en materia de formación y selección.',b:'Gestionar el Registro de Policías Locales.',c:'Estudiar y elaborar la normativa del IVASPE.',d:'Proponer la incoación de expedientes disciplinarios por la comisión de faltas leves, graves y muy graves, para el alumnado y el profesorado del IVASPE.'}, correct:'b', why:{b:'Gestionar el Registro de Policías Locales corresponde al Servicio de Gestión en Seguridad Pública, no a la Subdirección General de Formación (art.13.2 D.122/2017).'}},
{n:89, q:'El art.13.bis del D.122/2017 describe las funciones que, en particular, ejercerá la Subdirección General de Formación en Seguridad Pública y Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar la coordinación de los cuerpos de la policía local en la Comunitat Valenciana.',b:'Estudiar y proponer la realización de convenios para la formación en materia de seguridad y emergencias.',c:'Diseñar, planificar y coordinar otras actividades formativas en materia de seguridad pública, emergencias y protección civil.',d:'Ejercer funciones que deriven de las competencias asignadas a la AVSRE en materia de formación en seguridad pública y emergencias.'}, correct:'a', why:{a:'Gestionar la coordinación de los cuerpos de policía local no corresponde a la Subdirección General de Formación sino al Servicio de Régimen Jurídico (art.13.1 D.122/2017).'}},
{n:90, q:'Para el cumplimiento de las funciones que tiene encomendadas, la Subdirección General de Formación en Seguridad Pública y Emergencias de la AVSRE, tendrá bajo su dependencia:', o:{a:'El servicio de Régimen Jurídico y el servicio de Gestión en Seguridad Pública.',b:'El servicio de Formación de Seguridad Pública y el servicio de Formación de Emergencias.',c:'La Dirección General de Seguridad y Emergencias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art.13 bis D.122/2017 establece que bajo la Subdirección General de Formación están el Servicio de Formación de Seguridad Pública y el Servicio de Formación de Emergencias.'}},
{n:91, q:'El art.13 ter del D.122/2017 describe las funciones del Servicio de Formación de Seguridad Pública de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar la formación de las policías locales y del personal de la Unidad del Cuerpo Nacional de Policía adscrita a la Comunitat Valenciana.',b:'Gestionar el Registro de Policías Locales.',c:'Diseñar y gestionar el Plan Anual de Formación para el personal de seguridad.',d:'Tramitar los expedientes de homologación de los cursos que se realicen en materia de seguridad.'}, correct:'b', why:{b:'Gestionar el Registro de Policías Locales corresponde al Servicio de Gestión en Seguridad Pública, no al Servicio de Formación de Seguridad Pública (art.13 ter D.122/2017).'}},
{n:92, q:'El art.13 ter del D.122/2017 describe las funciones del Servicio de Formación de Seguridad Pública de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Coordinar los estudios e investigaciones en materia de seguridad a través del Centro de Investigación de Seguridad y Emergencias (CISE).',b:'Tramitar la acreditación profesional de las personas integrantes de las policías locales.',c:'Gestionar el Registro de Policías Locales.',d:'Cualquier función que se le encomiende en relación con las materias que le son propias.'}, correct:'c', why:{c:'Gestionar el Registro de Policías Locales corresponde al Servicio de Gestión en Seguridad Pública, no al Servicio de Formación de Seguridad Pública (art.13 ter D.122/2017).'}},
{n:93, q:'El art.13 ter del D.122/2017 describe las funciones del Servicio de Formación de Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar e impartir la formación del personal perteneciente a los servicios esenciales y complementarios de intervención frente a emergencias.',b:'Proponer la incoación de expedientes disciplinarios por la comisión de faltas leves, graves y muy graves, para el alumnado y el profesorado del IVASPE.',c:'Tramitar los expedientes de homologación de los cursos que se realicen en materia de emergencias.',d:'Coordinar los estudios e investigaciones en materia de emergencias a través del Centro de Investigación de Seguridad y Emergencias (CISE).'}, correct:'b', why:{b:'Proponer la incoación de expedientes disciplinarios para alumnado y profesorado del IVASPE no es función del Servicio de Formación de Emergencias (art.13 ter D.122/2017).'}},
{n:94, q:'Además de cualquier otra función que se le encomiende en relación con las materias que le son propias, según el art.13 ter del D.122/2017, al Servicio de Formación de Emergencias de la AVSRE le corresponde:', o:{a:'Diseñar y gestionar el Plan anual de formación para el personal de emergencias.',b:'Tramitar la acreditación profesional de las personas integrantes de las policías locales y de los servicios de emergencias.',c:'Gestionar el Registro de Policías Locales y bomberos.',d:'Le corresponden todas las funciones descritas en las respuestas anteriores.'}, correct:'a', why:{a:'El art.13 ter D.122/2017 atribuye al Servicio de Formación de Emergencias diseñar y gestionar el Plan Anual de formación para el personal de emergencias.'}},
{n:95, q:'Bajo la supervisión de la persona titular de la dirección de la AVSRE, la Subdirección General de Emergencias tiene atribuida:', o:{a:'La coordinación de los servicios y unidades adscritas a ella.',b:'La coordinación externa con otras administraciones públicas.',c:'La representación de la AVSRE en las tareas que se le encomienden.',d:'Todas las competencias descritas en las respuestas anteriores.'}, correct:'b', why:{b:'Conforme al D.122/2017, la Subdirección General de Emergencias tiene atribuida la coordinación externa con otras administraciones públicas, bajo supervisión de la Dirección.'}},
{n:96, q:'El art.14 del D.122/2017 describe las funciones que, en particular, ejercerá la Subdirección General de Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'La coordinación de los servicios de emergencia, así como las labores de atención e información ciudadana ante cualquier situación de emergencia.',b:'La planificación, diseño y coordinación de actividades formativas en materia de seguridad pública, emergencias y protección civil.',c:'La evaluación y análisis de las situaciones de riesgo y de emergencia.',d:'La elaboración de normativa, estudios de riesgos y funciones orientadas a la formación y sensibilización ciudadana en materia de protección civil.'}, correct:'b', why:{b:'La planificación y coordinación de actividades formativas corresponde a la Subdirección General de Formación, no a la de Emergencias (art.14 D.122/2017).'}},
{n:97, q:'Según el art.14 del D.122/2017, a la Subdirección General de Emergencias de la AVSRE le corresponde:', o:{a:'Ostentar la Secretaría de la Comisión de Protección Civil de la Comunitat Valenciana.',b:'La gestión de la intervención urgente de los servicios operativos ante situaciones de emergencia, así como la atención del teléfono único de emergencias europeo 112 Comunitat Valenciana.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'El art.14 D.122/2017 atribuye a la Subdirección General de Emergencias tanto la secretaría de la Comisión de Protección Civil como la gestión del 112 y la intervención urgente.'}},
{n:98, q:'El art.14 del D.122/2017 describe las funciones que corresponden a la Subdirección General de Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Coordinar y gestionar el acceso de los servicios de intervención a la red de comunicaciones de urgencias y emergencias de la Generalitat.',b:'Diseñar, planificar y coordinar actividades formativas en materia de seguridad pública, emergencias y protección civil.',c:'Llevar a cabo funciones de coordinación, gestión y planificación en materia de extinción de incendios.',d:'Llevar a cabo funciones de coordinación y gestión de las actuaciones de vuelta a la normalidad tras una situación de emergencia o catástrofe.'}, correct:'b', why:{b:'Diseñar y coordinar actividades formativas corresponde a la Subdirección General de Formación, no a la de Emergencias (art.14 D.122/2017).'}},
{n:99, q:'Para el cumplimiento de las funciones que tiene encomendadas, la Subdirección General de Emergencias de la AVSRE tendrá bajo su dependencia:', o:{a:'El Servicio de Coordinación de Emergencias y el Servicio de Planificación.',b:'El Servicio de Extinción de Incendios Forestales y el Servicio de Postemergencia.',c:'Los servicios citados en las respuestas a y b.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El art.14 D.122/2017 establece que la Subdirección General de Emergencias tiene bajo su dependencia el Servicio de Coordinación de Emergencias, el de Planificación, el de Extinción de Incendios Forestales y el de Postemergencia.'}},
{n:100, q:'El art.15.1 del D.122/2017 describe las funciones asignadas al Servicio de Coordinación de Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar la Sala de Emergencias de la Generalitat para el cumplimiento de las funciones asignadas en la Ley 13/2010.',b:'Elaborar los informes en materia de riesgos.',c:'Articular las actuaciones del personal técnico de la AVSRE en situaciones de emergencia.',d:'Establecer los criterios de coordinación con los diferentes Servicios operativos en el ámbito de la Comunitat Valenciana.'}, correct:'b', why:{b:'Elaborar los informes en materia de riesgos corresponde al Servicio de Planificación, no al Servicio de Coordinación de Emergencias (art.15.2 D.122/2017).'}},
{n:101, q:'El art.15.1 del D.122/2017 describe las funciones asignadas al Servicio de Coordinación de Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Desarrollar e investigar modelos de comportamiento de los incendios forestales.',b:'Gestionar las labores derivadas de la encomienda de funciones del Consejo de Seguridad Nuclear para la vigilancia radiológica ambiental del entorno de la Central Nuclear de Cofrentes.',c:'Gestionar las obligaciones establecidas para la Agencia, derivadas de su constitución como operadora de aeronaves tripuladas por control remoto.',d:'Redactar, implantar y mantener la operatividad del Plan Especial frente al Riesgo Radiológico de la Comunitat Valenciana.'}, correct:'a', why:{a:'Desarrollar e investigar modelos de comportamiento de incendios forestales corresponde al Servicio de Extinción de Incendios Forestales, no al de Coordinación de Emergencias (art.15.3 D.122/2017).'}},
{n:102, q:'El art.15.1 del D.122/2017 describe las funciones asignadas al Servicio de Coordinación de Emergencias de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Mantener la operatividad de los planes de protección civil de la Comunitat Valenciana.',b:'Establecer y garantizar la eficacia de las actuaciones derivadas de la obligación de la Generalitat en materia de asistencia a familiares y víctimas de accidentes de aviación civil.',c:'Gestionar las aportaciones económicas de la Generalitat a los consorcios provinciales de bomberos.',d:'Organizar simulacros de respuesta en situaciones de gran emergencia.'}, correct:'c', why:{c:'Gestionar las aportaciones económicas de la Generalitat a los consorcios provinciales de bomberos corresponde al Servicio de Planificación (art.15.2 D.122/2017).'}},
{n:103, q:'Además de cualquier otra función que se le encomiende en relación con las materias que le son propias, según el art.15.1 del D.122/2017, al Servicio de Coordinación de Emergencias de la AVSRE le corresponde:', o:{a:'Participar en el establecimiento de la operatividad de 112 Comunitat Valenciana y su relación con la Sala de Emergencias de la Generalitat.',b:'Gestionar las subvenciones, convenios y acuerdos de colaboración con las instituciones, personas y empresas proveedoras de servicios en materia de emergencias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.15.1 D.122/2017 atribuye al Servicio de Coordinación de Emergencias tanto la participación en la operatividad del 112 como la gestión de subvenciones y convenios.'}},
{n:104, q:'Además de cualquier otra función que se le encomiende en relación con las materias que le son propias, según el art.15.1 del D.122/2017, al Servicio de Coordinación de Emergencias de la AVSRE le corresponde:', o:{a:'Participar en las funciones que el Decreto 67/2020, del Consell, asigna en materia de protección civil, quedando exceptuadas las referidas a materia de autoprotección.',b:'Desarrollar la normativa establecida en la Ley 13/2010, de la Generalitat, en aquellas materias competencia del servicio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.15.1 D.122/2017 asigna al Servicio de Coordinación de Emergencias participar en las funciones del D.67/2020 (excepto autoprotección) y desarrollar la normativa de la Ley 13/2010.'}},
{n:105, q:'El art.15.2 del D.122/2017 describe las funciones atribuidas al Servicio de Planificación de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar las obligaciones establecidas para la Agencia, derivadas de su constitución como operadora de aeronaves tripuladas por control remoto.',b:'Elaborar, implantar y mantener la operatividad de los planes de protección civil de ámbito autonómico y asesoramiento a la Administración local.',c:'Elaborar los informes en materia de riesgos.',d:'Gestionar las líneas de subvención y los convenios de colaboración con las asociaciones y agrupaciones locales de voluntariado de protección civil.'}, correct:'a', why:{a:'Gestionar las obligaciones como operadora de aeronaves por control remoto corresponde al Servicio de Coordinación de Emergencias, no al de Planificación (art.15.1 D.122/2017).'}},
{n:106, q:'El art.15.2 del D.122/2017 describe las funciones atribuidas al Servicio de Planificación de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar los registros autonómicos de planes de autoprotección de las actividades con riesgo establecidos en el Decreto 32/2014, del Consell.',b:'Articular las actuaciones del personal técnico de la AVSRE en situaciones de emergencia.',c:'Gestionar las aportaciones económicas de la Generalitat a los consorcios provinciales de bomberos.',d:'Desarrollar normativamente la Ley 13/2010 y la ley 7/2011, ambas de la Generalitat, en aquellas materias competencia del Servicio.'}, correct:'b', why:{b:'Articular las actuaciones del personal técnico de la AVSRE en emergencias corresponde al Servicio de Coordinación de Emergencias, no al de Planificación (art.15.1 D.122/2017).'}},
{n:107, q:'El art.15.2 del D.122/2017 describe las funciones atribuidas al Servicio de Planificación de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Desarrollar las competencias que, en materia de protección civil, corresponden a la Generalitat Valenciana en aplicación del Real Decreto 840/2015.',b:'Ejercer la secretaría administrativa de la Comisión de Protección Civil y Emergencias de la Comunitat Valenciana y otros órganos colegiados.',c:'Mantener la operatividad de los planes de protección civil de la Comunitat Valenciana.',d:'Gestionar los expedientes de concesión de distinciones y condecoraciones al mérito de la Protección Civil.'}, correct:'c', why:{c:'Mantener la operatividad de los planes de protección civil corresponde al Servicio de Coordinación de Emergencias (art.15.1), no al de Planificación.'}},
{n:108, q:'Además de cualquier otra función que se le encomiende en relación con las materias que le son propias, y según el art.15.2 del D.122/2017, al Servicio de Planificación de la AVSRE le corresponde:', o:{a:'Colaborar con los organismos competentes en la implantación y el mantenimiento de la operatividad de los planes de emergencia o de autoprotección de presas, puertos y aeropuertos.',b:'Organizar, planificar y gestionar el Servicio de Bomberos Forestales y su actuación en el territorio de la Comunitat Valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.15.2 D.122/2017 atribuye al Servicio de Planificación colaborar en la operatividad de planes de emergencia de presas, puertos y aeropuertos. Organizar los Bomberos Forestales corresponde al Servicio de Extinción de Incendios.'}},
{n:109, q:'El art.15.3 del D.122/2017 describe las funciones asignadas al Servicio de Extinción de Incendios Forestales de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Organizar, planificar y gestionar el Servicio de Bomberos Forestales y su actuación en el territorio de la Comunitat Valenciana.',b:'Preparar y realizar el seguimiento técnico de la contratación de medios aéreos de la Generalitat para la extinción de incendios forestales.',c:'Gestionar los expedientes de concesión de distinciones y condecoraciones al mérito de la Protección Civil.',d:'Organizar, planificar y gestionar los medios y recursos aéreos de la Generalitat para la extinción de incendios forestales.'}, correct:'c', why:{c:'Gestionar los expedientes de distinciones al mérito de la Protección Civil corresponde al Servicio de Planificación (art.15.2 D.122/2017).'}},
{n:110, q:'El art.15.3 del D.122/2017 describe las funciones asignadas al Servicio de Extinción de Incendios Forestales de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar las aportaciones económicas de la Generalitat a los consorcios provinciales de bomberos.',b:'Preparar y realizar el seguimiento técnico del arrendamiento o adquisición de vehículos y del equipamiento del Servicio de Bomberos Forestales.',c:'Preparar y realizar el seguimiento técnico de la redacción y ejecución de proyectos de construcción de inmuebles e infraestructuras del Servicio de Bomberos Forestales.',d:'Gestionar el mantenimiento del equipamiento, inmuebles e infraestructuras adscritas al Servicio de Bomberos Forestales.'}, correct:'a', why:{a:'Gestionar las aportaciones económicas de la Generalitat a los consorcios de bomberos corresponde al Servicio de Planificación (art.15.2 D.122/2017).'}},
{n:111, q:'El art.15.3 del D.122/2017 describe las funciones asignadas al Servicio de Extinción de Incendios Forestales de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Actuar como gestor de los helipuertos y aeródromos de extinción de incendios forestales de la Generalitat.',b:'Valorar los gastos de la intervención de los medios y recursos de la Generalitat en la extinción de incendios forestales.',c:'Gestionar las aportaciones económicas de la Generalitat a los consorcios provinciales de bomberos.',d:'Coordinar la operativa de los diferentes organismos dependientes de la Generalitat en la investigación de causas de los incendios forestales.'}, correct:'c', why:{c:'Gestionar las aportaciones económicas a los consorcios provinciales de bomberos corresponde al Servicio de Planificación (art.15.2), no al de Extinción de Incendios Forestales (art.15.3 D.122/2017).'}},
{n:112, q:'Además de cualquier otra función que se le encomiende en relación con las materias que le son propias, y según el art.15.3 del D.122/2017, al Servicio de Extinción de Incendios Forestales de la AVSRE le corresponde:', o:{a:'Desarrollar e investigar modelos de comportamiento de los incendios forestales.',b:'Colaborar en la coordinación e implantación operativa de los diferentes organismos y empresas intervinientes en la extinción de incendios forestales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.15.3 D.122/2017 atribuye al Servicio de Extinción de Incendios Forestales tanto desarrollar e investigar modelos de comportamiento de incendios como colaborar en la coordinación operativa.'}},
{n:113, q:'El art.15.4 del D.122/2017 describe las funciones asignadas al Servicio de Postemergencia de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar y coordinar las actuaciones para la vuelta a la normalidad tras una situación de emergencia o catástrofe y prestar apoyo técnico a la Oficina Única Postemergencia.',b:'Mantener la operatividad de los planes de protección civil de la Comunitat Valenciana.',c:'Ejecutar la reparación de los daños ocasionados por situaciones de emergencia que corresponda a la Generalitat en el marco de la Oficina Única Postemergencia.',d:'Desarrollar la normativa establecida en la Ley 13/2010 en aquellas materias competencia del servicio.'}, correct:'b', why:{b:'Mantener la operatividad de los planes de protección civil corresponde al Servicio de Coordinación de Emergencias (art.15.1), no al Servicio de Postemergencia.'}},
{n:114, q:'Además de cualquier otra función que se le encomiende en relación con las materias que le son propias, y según el art.15.4 del D.122/2017, el Servicio de Postemergencia de la AVSRE tiene asignado:', o:{a:'Mantener la operatividad de los planes de protección civil de la Comunitat Valenciana.',b:'Realizar el estudio de las estimaciones de los daños presentados por los afectados, tramitar y realizar el seguimiento de los expedientes de ayudas en el marco de la Oficina Única Postemergencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.15.4 D.122/2017 atribuye al Servicio de Postemergencia el estudio de daños, tramitación y seguimiento de expedientes de ayuda en el marco de la Oficina Única Postemergencia.'}},
{n:115, q:'Además de cualquier otra función que se le encomiende en relación con las materias que le son propias, y según el art.15.4 del D.122/2017, el Servicio de Postemergencia de la AVSRE tiene asignado:', o:{a:'Elaborar los informes y propuestas de resolución de los recursos administrativos y reclamaciones presentadas en relación con los expedientes de ayudas de la Oficina Única Postemergencia.',b:'Mantener la operatividad de los planes de protección civil de la Comunitat Valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.15.4 D.122/2017 asigna al Servicio de Postemergencia elaborar los informes y propuestas de resolución de recursos sobre expedientes de ayudas de la Oficina Única Postemergencia.'}},
{n:116, q:'Dependiente directamente de la persona titular de la Dirección de la AVSRE y con rango de subdirección general, ejerce la dirección, coordinación y supervisión de los servicios generales de la AVSRE:', o:{a:'La Secretaría Administrativa de Gestión.',b:'La Secretaría Técnica.',c:'La Secretaría Técnico-Administrativa de Gestión.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art.16 D.122/2017 establece que la Secretaría Técnica, con rango de subdirección general, ejerce la dirección, coordinación y supervisión de los servicios generales de la AVSRE.'}},
{n:117, q:'El art.16 del D.122/2017 describe las funciones que corresponden a la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Atender las necesidades de los órganos de gobierno, coordinación y consultivos, como también los registros de estos.',b:'Apoyar y dar soporte técnico a la Secretaría Técnica en las funciones que le son propias, cuando no corresponda expresamente a otra Unidad.',c:'Coordinar y elaborar las propuestas de mejora de los procedimientos administrativos.',d:'Coordinar e impulsar la tramitación de proyectos normativos y convocatorias de subvenciones y ayudas.'}, correct:'b', why:{b:'Apoyar y dar soporte técnico a la Secretaría Técnica no es función de la propia Secretaría Técnica sino de sus unidades dependientes (art.16 D.122/2017).'}},
{n:118, q:'El art.16 del D.122/2017 describe las funciones que corresponden a la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Supervisar y realizar el seguimiento del funcionamiento correcto del Registro de entrada y salida de documentos.',b:'Gestionar la formación continua del personal adscrito a cada Unidad.',c:'Gestionar el material móvil de la AVSRE.',d:'Gestionar el personal de la AVSRE.'}, correct:'b', why:{b:'Gestionar la formación continua del personal no es función de la Secretaría Técnica de la AVSRE según el art.16 D.122/2017; corresponde a la Subdirección General de Formación.'}},
{n:119, q:'El art.16 del D.122/2017 describe las funciones que corresponden a la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Elaborar las propuestas de modificación de las relaciones de puestos de trabajo del personal adscrito a la AVSRE.',b:'Tramitar las incidencias en nómina y situaciones de personal.',c:'Elaborar y realizar el análisis mensual del periodo medio de pago.',d:'Gestionar las nóminas e indemnizaciones por razón del servicio.'}, correct:'c', why:{c:'Elaborar el análisis mensual del periodo medio de pago corresponde al Servicio Económico y Presupuestario, no a la Secretaría Técnica (art.16.2 D.122/2017).'}},
{n:120, q:'El art.16 del D.122/2017 describe las funciones que corresponden a la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Custodiar y mantener los expedientes de personal.',b:'Elaborar los informes y propuestas de resolución respecto de los recursos administrativos y reclamaciones, salvo lo dispuesto en el artículo 15.4.e del citado decreto.',c:'Gestionar las actuaciones derivadas de la tesorería propia de la AVSRE.',d:'Gestionar y tramitar las sentencias judiciales firmes en materia de personal.'}, correct:'c', why:{c:'Gestionar las actuaciones de tesorería corresponde al Servicio Económico y Presupuestario, no a la Secretaría Técnica (art.16.2 D.122/2017).'}},
{n:121, q:'El art.16 del D.122/2017 describe las funciones que corresponden a la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar las actuaciones derivadas de la tesorería propia de la AVSRE.',b:'Realizar el seguimiento de la ejecución de los expedientes de contratación.',c:'Realizar el seguimiento de los expedientes de compras centralizadas y de los suministros menores de la AVSRE.',d:'Realizar todas las actuaciones relativas a los arrendamientos de bienes inmuebles.'}, correct:'a', why:{a:'Gestionar las actuaciones de tesorería corresponde al Servicio Económico y Presupuestario, no a la Secretaría Técnica (art.16.2 D.122/2017).'}},
{n:122, q:'El art.16 del D.122/2017 describe las funciones que corresponden a la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Verificar y validar los planes de autoprotección elaborados por la Subsecretaría de Emergencias.',b:'Coordinar la gestión del mantenimiento de los distintos inmuebles adscritos a la AVSRE.',c:'Elaborar la planificación y programación económica.',d:'Coordinar e impulsar la elaboración del anteproyecto de presupuestos y de las modificaciones presupuestarias.'}, correct:'a', why:{a:'Verificar y validar planes de autoprotección no es función de la Secretaría Técnica sino del Servicio de Planificación (art.15.2 D.122/2017).'}},
{n:123, q:'El art.16 del D.122/2017 describe las funciones que corresponden a la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar y realizar el seguimiento y control de la ejecución presupuestaria y económica de la AVSRE.',b:'Informar los expedientes disciplinarios que se generen en el organismo autónomo.',c:'Tramitar y formalizar los ingresos que se originan por las actividades propias de la AVSRE.',d:'Coordinar el Registro Único de Facturas (RUF).'}, correct:'b', why:{b:'Informar expedientes disciplinarios no es función de la Secretaría Técnica según el art.16 D.122/2017.'}},
{n:124, q:'El art.16.1 del D.122/2017 describe las funciones que corresponden a la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Gestionar y tramitar la concesión de distinciones a personal adscrito a la AVSRE.',b:'Coordinar y realizar el seguimiento de las distintas cajas, así como también de la contabilización de las cuentas justificativas de los fondos de caja fija.',c:'Elaborar los informes sobre cualquier norma en materia que sea competencia de la AVSRE con repercusión en el gasto público.',d:'Apoyar administrativamente a la Oficina Única Postemergencia.'}, correct:'a', why:{a:'Gestionar y tramitar la concesión de distinciones a personal adscrito a la AVSRE no figura entre las funciones del art.16.1 D.122/2017; corresponde al Servicio de Gestión en Seguridad Pública.'}},
{n:125, q:'Además de cualquier otra función que le sea encomendada en relación con las materias que le son propias, y según el art.16 del D.122/2017, a la Secretaría Técnica de la AVSRE le corresponde:', o:{a:'Coordinar el mantenimiento y la actualización de los contenidos de la página web de la AVSRE.',b:'Ejercer las funciones que le corresponde como Unidad de Transparencia del organismo.',c:'Gestionar y tramitar las quejas y sugerencias, así como las preguntas parlamentarias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.16 D.122/2017 atribuye a la Secretaría Técnica el mantenimiento de la web, las funciones de transparencia y la gestión de quejas y preguntas parlamentarias.'}},
{n:126, q:'El art.16.2 del D.122/2017 establece cuales son las Unidades Administrativas dependientes de la Secretaría Técnica de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'El Servicio Económico y Presupuestario.',b:'El Servicio de Formación.',c:'El Servicio de Contratación.',d:'El Servicio de Gestión Administrativa y Apoyo Técnico.'}, correct:'b', why:{b:'El Servicio de Formación no depende de la Secretaría Técnica sino de la Subdirección General de Formación en Seguridad Pública y Emergencias (art.16.2 y art.13 bis D.122/2017).'}},
{n:127, q:'El art.16.2 del D.122/2017 describe las funciones asignadas al Servicio Económico y Presupuestario de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Apoyar administrativamente a la Oficina Económica Única.',b:'Elaborar el presupuesto y tramitar sus modificaciones.',c:'Gestionar los ingresos y gastos del organismo.',d:'Elaborar y realizar el análisis mensual del periodo medio de pago.'}, correct:'a', why:{a:'Apoyar administrativamente a la Oficina Económica Única no figura entre las funciones del Servicio Económico y Presupuestario en el art.16.2 D.122/2017.'}},
{n:128, q:'El art.16.2 del D.122/2017 describe las funciones asignadas al Servicio Económico y Presupuestario de la AVSRE. Indique cual de las siguientes no es una de ellas.', o:{a:'Coordinar y elaborar la información económica que solicite la Sindicatura de Comptes, la Intervención General u otros órganos superiores.',b:'Valorar los gastos de la intervención de los medios y recursos de la Generalitat en materia de seguridad y emergencias.',c:'Apoyar y dar soporte técnico a la Secretaría Técnica en las funciones que le son propias.',d:'Asesorar en la planificación, programación, seguimiento y evaluación de las inversiones del organismo.'}, correct:'b', why:{b:'Valorar los gastos de intervención de medios de la Generalitat en seguridad y emergencias no es función del Servicio Económico y Presupuestario según el art.16.2 D.122/2017.'}},
{n:129, q:'De conformidad con lo establecido en el art.16.2 del D.122/2017, corresponde al Servicio Económico y Presupuestario de la AVSRE:', o:{a:'Gestionar las actuaciones derivadas de la tesorería propia de la AVSRE.',b:'Gestionar las nóminas e indemnizaciones por razón del servicio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.16.2 D.122/2017 atribuye al Servicio Económico y Presupuestario gestionar las actuaciones de tesorería. Las nóminas corresponden a la Secretaría Técnica.'}},
{n:130, q:'De conformidad con lo establecido en el art.16.2 del D.122/2017, corresponde al Servicio Económico y Presupuestario de la AVSRE:', o:{a:'Realizar las tareas materiales tendentes a la formulación de las cuentas anuales de la AVSRE, de acuerdo con los principios contables aplicables.',b:'Tramitar, gestionar y formalizar los contratos menores.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.16.2 D.122/2017 asigna al Servicio Económico y Presupuestario elaborar las cuentas anuales. Los contratos menores corresponden al Servicio de Contratación.'}},
{n:131, q:'El art.16.2 del D.122/2017 describe las funciones asignadas al Servicio de Contratación de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Analizar, diseñar, determinar y ordenar los criterios en relación con las contrataciones que se efectúan y elaborar los informes y propuestas de resolución.',b:'Tramitar las convocatorias de ayudas y subvenciones, así como la actualización de las mismas en procedimientos GUC, referidas al ámbito competencial de la AVSRE.',c:'Estudiar, tramitar, gestionar, preparar y formalizar los expedientes de contratación.',d:'Gestionar las adquisiciones de material de tipo general necesario para el funcionamiento normal del organismo.'}, correct:'b', why:{b:'Tramitar convocatorias de ayudas y subvenciones en procedimientos GUC corresponde al Servicio de Gestión Administrativa y Apoyo Técnico, no al Servicio de Contratación (art.16.2 D.122/2017).'}},
{n:132, q:'El art.16.2 del D.122/2017 describe las funciones asignadas al Servicio de Contratación de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Asesorar y emitir los informes que en su ámbito de actuación les sean requeridos.',b:'Elaboración de la propuesta de programación de la contratación de la AVSRE.',c:'Apoyar administrativamente a la Oficina Económica Única.',d:'Tramitar y gestionar los encargos a medios propios.'}, correct:'c', why:{c:'Apoyar administrativamente a la Oficina Económica Única no es función del Servicio de Contratación según el art.16.2 D.122/2017.'}},
{n:133, q:'De conformidad con lo establecido en el art.16.2 del D.122/2017, ¿Qué Unidad Administrativa de la AVSRE tiene asignado tramitar, gestionar y formalizar los contratos menores de la AVSRE?', o:{a:'El Servicio Jurídico.',b:'El Servicio de Contratación.',c:'El Servicio Económico y Presupuestario.',d:'El Servicio de Gestión Administrativa y Apoyo Técnico.'}, correct:'b', why:{b:'El art.16.2 D.122/2017 asigna al Servicio de Contratación tramitar, gestionar y formalizar los contratos menores de la AVSRE.'}},
{n:134, q:'De conformidad con lo establecido en el art.16.2 del D.122/2017, ¿Qué Unidad Administrativa de la AVSRE tiene asignado tramitar expedientes de responsabilidad patrimonial referidos al ámbito competencial de la AVSRE?', o:{a:'El Servicio Jurídico.',b:'El Servicio de Contratación.',c:'El Servicio Económico y Presupuestario.',d:'El Servicio de Gestión Administrativa y Apoyo Técnico.'}, correct:'d', why:{d:'El art.16.2 D.122/2017 asigna al Servicio de Gestión Administrativa y Apoyo Técnico tramitar los expedientes de responsabilidad patrimonial referidos al ámbito competencial de la AVSRE.'}},
{n:135, q:'El art.16.2 del D.122/2017 describe las funciones asignadas al Servicio de Gestión Administrativa y Apoyo Técnico de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Apoyar a la Secretaría Técnica, con arreglo a criterios de competencia técnica y desde una perspectiva pluridisciplinar.',b:'Gestionar las adquisiciones de material de tipo general necesario para el funcionamiento normal del organismo.',c:'Tramitar las convocatorias de ayudas y subvenciones en procedimientos GUC, referidas al ámbito competencial de la AVSRE.',d:'Tramitar los convenios de colaboración referidos al ámbito competencial de la AVSRE.'}, correct:'b', why:{b:'Gestionar las adquisiciones de material de tipo general corresponde al Servicio de Contratación, no al Servicio de Gestión Administrativa y Apoyo Técnico (art.16.2 D.122/2017).'}},
{n:136, q:'El art.16.2 del D.122/2017 describe las funciones asignadas al Servicio de Gestión Administrativa y Apoyo Técnico de la AVSRE. Indique cual de las siguientes no es una de ellas:', o:{a:'Gestionar y llevar a cabo los informes, memorias y estudios técnicos que se requieran, referidos al ámbito competencial de la AVSRE.',b:'Supervisar y actualizar la normativa vigente relacionada con las materias que le son propias al organismo.',c:'Tramitar los proyectos de disposiciones normativas de carácter general referidos al ámbito competencial de la AVSRE.',d:'Elaborar propuestas de formación técnica para incluirlas en la programación de la AVSRE.'}, correct:'d', why:{d:'Elaborar propuestas de formación técnica para la programación de la AVSRE no figura entre las funciones del Servicio de Gestión Administrativa y Apoyo Técnico (art.16.2 D.122/2017).'}},
{n:137, q:'Con respecto a los diferentes órganos de la AVSRE, regulados en la Ley 17/2017, Ley 4/2017 y D.122/2017, indique la afirmación incorrecta:', o:{a:'Los Consejos Supramunicipales de Coordinación de las Policías Locales son órganos colegiados de coordinación y asesoramiento, adscritos a la AVSRE.',b:'Los Consejos Supramunicipales de Coordinación de las Policías Locales pueden constituirse en aquellos ámbitos territoriales en los que existan cuestiones de seguridad pública comunes a varios municipios, previa consulta a los ayuntamientos afectados.',c:'El Comité de Ética y Transparencia prestará servicios de asesoramiento, averiguación e investigación de actos y situaciones contrarios al ordenamiento jurídico, que pudieran realizar los componentes de los cuerpos de policía local.',d:'El Observatorio de Seguridad de la Comunitat Valenciana es un órgano de participación, consulta, deliberación, análisis, estudio, asesoramiento y prospectiva en materia de seguridad.'}, correct:'c', why:{c:'Prestar servicios de asesoramiento, averiguación e investigación de actos contrarios al ordenamiento corresponde al Comité de Asuntos Internos, no al Comité de Ética y Transparencia (Ley 17/2017).'}},
{n:138, q:'En la Comunitat Valenciana, la Comisión de Coordinación de Policías Locales es el máximo órgano de participación institucional, consultivo y deliberante en esta materia. Indique cual de las siguientes no es una de sus funciones:', o:{a:'Promocionar convenios y acuerdos con las instituciones de otras administraciones públicas.',b:'Informar los anteproyectos de ley, proyectos de reglamentos y cualesquiera otras disposiciones relacionadas con la actuación de las Policías Locales que se elaboren en la Comunitat Valenciana.',c:'Proponer a los órganos competentes la adopción de cuantas medidas consideren convenientes para la mejora de los servicios y homogeneización de medios técnicos.',d:'Conocer de la programación de los cursos y demás actividades de formación de las Policías Locales que se realicen.'}, correct:'a', why:{a:'Promocionar convenios y acuerdos con instituciones de otras administraciones no es función de la Comisión de Coordinación de Policías Locales (Ley 17/2017); corresponde al IVASPE.'}},
{n:139, q:'En la Comunitat Valenciana, corresponde a la Comisión de Coordinación de Policías Locales:', o:{a:'Proponer planes de actuación conjunta entre diversos cuerpos de policía local para la presentación a los ayuntamientos que lo hubiesen solicitado.',b:'Ejercer funciones de mediación y arbitraje en los conflictos colectivos de carácter profesional de los cuerpos de Policía Local, cuando lo soliciten de común acuerdo el ayuntamiento afectado y la representación sindical.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Conforme a la Ley 17/2017, la Comisión de Coordinación de Policías Locales puede proponer planes de actuación conjunta y ejercer funciones de mediación y arbitraje en conflictos colectivos.'}},
{n:140, q:'El Gabinete Técnico de Coordinación de Policías Locales.', o:{a:'Es un órgano colegiado de carácter técnico, adscrito a la AVSRE, al que corresponde prestar asesoramiento y apoyo técnico en materia de coordinación.',b:'Intervendrá preceptivamente en la realización de los trabajos de documentación, preparación de informes, asesoramiento, propuesta y demás actividades que se le encomienden por la Comisión de Coordinación de Policías Locales.',c:'Podrá realizar sus funciones a iniciativa de las alcaldías o de los órganos superiores de otras administraciones públicas de la Comunitat Valenciana.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 17/2017 recoge todas las características citadas del Gabinete Técnico de Coordinación de Policías Locales.'}},
{n:141, q:'El Gabinete Técnico de Coordinación de Policías Locales de la Comunitat Valenciana se reunirá cuantas veces sea preciso, y en todo caso:', o:{a:'Tres veces al año.',b:'Dos veces al año.',c:'Una vez al año.',d:'Una vez cada tres meses.'}, correct:'b', why:{b:'La Ley 17/2017 establece que el Gabinete Técnico de Coordinación de Policías Locales se reunirá cuantas veces sea preciso y, en todo caso, dos veces al año.'}},
{n:142, q:'Con respecto al Comité de Ética y Transparencia en la Actividad Policial de la Comunitat Valenciana, según lo establecido en la Ley 17/2017:', o:{a:'Es un órgano adscrito a la AVSRE, de carácter consultivo en materia de ética y deontología, con la finalidad de coadyuvar a mejorar la calidad del servicio policial.',b:'Sus integrantes desarrollarán sus funciones de acuerdo con los principios de independencia, objetividad, imparcialidad e integridad personal.',c:'Sus miembros serán nombrados para un periodo de cuatro años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'La Ley 17/2017 recoge todas las características del Comité de Ética y Transparencia: órgano consultivo adscrito a la AVSRE, principios de independencia y miembros nombrados por cuatro años.'}},
{n:143, q:'Con respecto al Comité de Asuntos Internos, según los establecido en la ley 17/2017, indique la afirmación incorrecta:', o:{a:'Está adscrito a la AVSRE y es un órgano especializado de colaboración con la administración local en el control de la legalidad de la actuación de los integrantes de los cuerpos de policía local.',b:'Estará compuesto por once personas, todas funcionarias del grupo A1 o A2. Siete de ellas pertenecerán a cuerpos de policía local de la Comunitat Valenciana.',c:'Prestará servicios de asesoramiento, averiguación e investigación de actos y situaciones contrarios al ordenamiento jurídico, que pudieran realizar los componentes de los cuerpos de policía local, y actuará previa petición de la máxima instancia del ayuntamiento respectivo.',d:'Le corresponde proponer, a instancia de la alcaldía correspondiente, una terna de funcionarios/as para el desempeño de las funciones de instructor/a y secretario/a en los procedimientos disciplinarios por infracciones graves y muy graves.'}, correct:'b', why:{b:'El Comité de Asuntos Internos no está compuesto exclusivamente por funcionarios del grupo A1 o A2, ni con esa distribución exacta, según la Ley 17/2017. La afirmación incorrecta es la b.'}},
{n:144, q:'La Ley 17/2017 se refiere al IVASPE:', o:{a:'En la sección segunda del capítulo II de su Título II.',b:'En la sección primera del capítulo II de su Título II.',c:'En la sección tercera del capítulo I de su Título II.',d:'En la sección segunda del capítulo I de su Título II.'}, correct:'b', why:{b:'La Ley 17/2017 regula el IVASPE en la Sección Primera del Capítulo II de su Título II.'}},
{n:145, q:'La Ley 17/2017 regula el IVASPE:', o:{a:'En sus artículos 15 y 16.',b:'En sus artículos 16 y 17.',c:'En sus artículos 15 al 17.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'La Ley 17/2017 regula el IVASPE en sus artículos 15 y 16.'}},
{n:146, q:'El IVASPE adquiere esta denominación mediante la:', o:{a:'Ley 10/2010, de Presupuestos de la Generalitat Valenciana.',b:'Ley 16/2010, de Medidas Fiscales, de Gestión Administrativa y Financiera, y de Organización de la Generalitat.',c:'Ley 17/2017 de Coordinación de Policías Locales de la Comunitat Valenciana.',d:'Ley 10/2010, de 9 de julio, de la Generalitat, de Ordenación y Gestión de la Función Pública Valenciana.'}, correct:'b', why:{b:'El IVASPE adquiere su denominación actual mediante la Ley 16/2010, de Medidas Fiscales, de Gestión Administrativa y Financiera, y de Organización de la Generalitat.'}},
{n:147, q:'El IVASPE es un órgano adscrito:', o:{a:'Al Consell.',b:'A la Consellería competente en materia de Policía.',c:'Al Gabinete Técnico de la Presidencia.',d:'A la AVSRE.'}, correct:'d', why:{d:'Conforme al art.19 D.122/2017 y la Ley 17/2017, el IVASPE está adscrito a la AVSRE.'}},
{n:148, q:'Según el art.19 del D.122/2017, el IVASPE es el órgano con competencias en materia de investigación, formación y perfeccionamiento profesional, entre otros, de:', o:{a:'Las Policías Locales de la Comunitat Valenciana.',b:'Los Bomberos de la Comunitat Valenciana.',c:'El personal de Protección Civil de la Comunitat Valenciana.',d:'Todo el personal citado en las respuestas anteriores.'}, correct:'d', why:{d:'El art.19 D.122/2017 atribuye al IVASPE competencias de investigación, formación y perfeccionamiento de las Policías Locales, Bomberos y personal de Protección Civil.'}},
{n:149, q:'Según el art.15 de la Ley 17/2017, al IVASPE le corresponde:', o:{a:'La formación y perfeccionamiento profesional de las Policías Locales, y el desarrollo de la investigación en esta materia.',b:'Valorar y difundir el conocimiento científico y la doctrina más relevante emanada de la práctica judicial de aplicación al campo de la ética policial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.15 Ley 17/2017 atribuye al IVASPE la formación, perfeccionamiento profesional de las Policías Locales y el desarrollo de la investigación en esta materia.'}},
{n:150, q:'En la Comunitat Valenciana, el desarrollo y mantenimiento de un sistema bibliográfico, documental y de información legislativa, con atención preferente a la administración municipal y a las policías locales, es función:', o:{a:'Del Gabinete Técnico de Coordinación de Policías Locales.',b:'Del IVASPE.',c:'De la AVSRE.',d:'De la Comisión de Coordinación de Policías Locales.'}, correct:'b', why:{b:'Conforme al art.16 Ley 17/2017, el desarrollo y mantenimiento del sistema bibliográfico con atención preferente a la administración municipal y policías locales es función del IVASPE.'}},
{n:151, q:'El art.16 de la Ley 17/2017 describe las funciones del IVASPE. Indique cual de las siguientes no es una de ellas:', o:{a:'La información y el asesoramiento a las entidades locales en materia de policía local.',b:'La participación preceptiva en la realización de los trabajos de documentación, preparación de informes, asesoramiento y propuesta de la AVSRE.',c:'La creación del marco en el que se deberá desarrollar el apoyo y la colaboración interpolicial en materia de información, actuaciones conjuntas y prestaciones recíprocas de carácter temporal y extraordinario.',d:'La participación en los procesos de selección, formación y promoción de las distintas escalas y categorías de los cuerpos de policía local.'}, correct:'b', why:{b:'La participación preceptiva en trabajos de documentación y asesoramiento de la AVSRE no figura entre las funciones del IVASPE en el art.16 Ley 17/2017; corresponde al Gabinete Técnico.'}},
{n:152, q:'Según los establecido en el art.16 de la Ley 17/2017:', o:{a:'El IVASPE será responsable del desarrollo y mantenimiento de un sistema bibliográfico, documental y de información legislativa, con atención preferente a la administración municipal y a las policías locales.',b:'El IVASPE se constituye como referencia para el estudio, diseño y planificación de los estudios académicos relacionados con la seguridad pública.',c:'Se garantizará la actividad del IVASPE, en relación con la realización de pruebas e impartición de cursos, en las tres provincias de la Comunitat Valenciana.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.16 Ley 17/2017 recoge todas las afirmaciones: sistema bibliográfico, referencia académica y garantía de actividad en las tres provincias.'}},
{n:153, q:'Según los establecido en el art.16 de la Ley 17/2017, la promoción de convenios y acuerdos con las instituciones docentes competentes, es competencia:', o:{a:'Del IVASPE.',b:'Del Gabinete Técnico de Coordinación de Policías Locales.',c:'De la AVSRE.',d:'De la Comisión de Coordinación de Policías Locales.'}, correct:'a', why:{a:'El art.16 Ley 17/2017 atribuye al IVASPE la promoción de convenios y acuerdos con instituciones docentes competentes para homologar cursos.'}},
{n:154, q:'Corresponde al IVASPE la organización e impartición de cursos...', o:{a:'De post grado.',b:'De capacitación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.16 Ley 17/2017 atribuye al IVASPE la organización e impartición de cursos de capacitación, entre otros.'}},
{n:155, q:'Corresponde al IVASPE la organización e impartición de cursos...', o:{a:'Básicos.',b:'De perfeccionamiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.16 Ley 17/2017 atribuye al IVASPE la organización e impartición de cursos básicos y de perfeccionamiento.'}},
{n:156, q:'Corresponde al IVASPE:', o:{a:'La información y el asesoramiento a las entidades locales en materia de Policía Local.',b:'Requerir a los órganos competentes de las diversas administraciones públicas la adopción de cuantas medidas considere convenientes para la mejora de los servicios de las Policías Locales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art.16 Ley 17/2017 atribuye al IVASPE la información y asesoramiento a las entidades locales en materia de Policía Local.'}},
{n:157, q:'Corresponde al IVASPE:', o:{a:'La creación del marco en el que se deberá desarrollar el apoyo y la colaboración interpolicial en materia de información, actuaciones conjuntas y prestaciones recíprocas de carácter temporal y extraordinario.',b:'La promoción de convenios y acuerdos con las instituciones docentes competentes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.16 Ley 17/2017 atribuye al IVASPE tanto la creación del marco de colaboración interpolicial como la promoción de convenios con instituciones docentes.'}},
{n:158, q:'Corresponde al IVASPE:', o:{a:'Analizar, estudiar e informar, de oficio o a instancia de parte, las diferentes cuestiones en materia de seguridad pública que acontezcan en la Comunitat Valenciana.',b:'La participación en los procesos de selección, formación y promoción de las distintas escalas y categorías de los cuerpos de Policía Local.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art.16 Ley 17/2017 atribuye al IVASPE la participación en los procesos de selección, formación y promoción de las distintas escalas y categorías de policía local.'}},
{n:159, q:'El IVASPE:', o:{a:'Colabora con las instituciones universitarias en el establecimiento de estudios de alto nivel en materia de seguridad.',b:'Imparte cursos en las tres provincias de la Comunitat Valenciana.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.16 Ley 17/2017 establece que el IVASPE colabora con universidades en estudios de alto nivel y garantiza su actividad en las tres provincias de la Comunitat Valenciana.'}},
{n:160, q:'En la Comunitat Valenciana, la superación de los cursos de formación básica de Policías Locales de nuevo ingreso, así como los de ascenso o promoción de las diferentes categorías...', o:{a:'Exime de volver a realizarlos durante los tres años siguientes.',b:'Constituye un requisito necesario para la adquisición de la condición de funcionario de carrera, cuando sean preceptivos para el acceso a las diferentes escalas y categorías.',c:'Constituyen mérito valuable en los concursos en los que pudieran participar los interesados.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'Conforme al art.16 Ley 17/2017, la superación de cursos del IVASPE constituye requisito para acceder a la condición de funcionario de carrera (cuando sean preceptivos) y mérito en concursos.'}},
{n:161, q:'De conformidad con lo dispuesto en el D.122/2017, en la AVSRE, la gestión del IVASPE le corresponde:', o:{a:'Al Servicio de Formación en Seguridad y Emergencias dependiente de la Subdirección General de Seguridad.',b:'Al Servicio de Formación en Seguridad y Emergencias dependiente de la Subdirección General de Emergencias.',c:'Al Servicio de Seguridad Pública dependiente de la Subdirección General de Seguridad.',d:'Al Servicio de Seguridad Pública dependiente de la Subdirección General de Emergencias.'}, correct:'a', why:{a:'El D.122/2017 atribuye la gestión del IVASPE al Servicio de Formación de Seguridad Pública dependiente de la Subdirección General de Formación en Seguridad Pública y Emergencias.'}},
{n:162, q:'Según el art.19 del D.122/2017, el IVASPE es el órgano con competencias en materia de investigación, formación y perfeccionamiento profesional de las Policías Locales, Bomberos y personal de Protección Civil de la Comunitat Valenciana, cuyas líneas estratégicas están orientadas al:', o:{a:'Enriquecimiento del capital humano y su cualificación mediante la formación, la innovación y la búsqueda de la excelencia.',b:'Compromiso de generar y transferir las bases de conocimiento para la mejora de las políticas en materia de seguridad y emergencias.',c:'Impulso de un modelo de mejora continua que posibilite la eficacia, la eficiencia y la calidad en los servicios de seguridad pública y emergencias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.19 D.122/2017 establece que las líneas estratégicas del IVASPE se orientan a todas las directrices citadas: enriquecimiento del capital humano, generación de conocimiento e impulso de la mejora continua.'}},
{n:163, q:'El IVASPE ejerce funciones de investigación, formación y perfeccionamiento profesional de:', o:{a:'Policías Locales.',b:'Bomberos.',c:'Personal de Protección Civil.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art.19 D.122/2017 y la Ley 17/2017 establecen que el IVASPE ejerce funciones para Policías Locales, Bomberos y personal de Protección Civil de la Comunitat Valenciana.'}},
{n:164, q:'La Ley 13/2010 de Protección Civil y Gestión de Emergencias de la Generalitat Valenciana asigna al IVASPE:', o:{a:'La investigación, formación y perfeccionamiento de los servicios de intervención en materia de protección civil y gestión de emergencias.',b:'La elaboración de protocolos operativos en materia de protección civil y gestión de emergencias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'La Ley 13/2010 de la Generalitat asigna al IVASPE la investigación, formación y perfeccionamiento de los servicios de intervención en protección civil y gestión de emergencias.'}},
{n:165, q:'En materia de protección civil y gestión de emergencias de la Generalitat Valenciana, es competencia del IVASPE organizar e impartir los cursos de formación básica de nuevo ingreso y los de formación continua:', o:{a:'Del personal de los servicios esenciales de intervención frente a emergencias.',b:'Del personal de los servicios complementarios de intervención.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Conforme a la Ley 13/2010 y la Ley 17/2017, el IVASPE organiza e imparte formación básica y continua tanto del personal de servicios esenciales como del complementario de intervención.'}},
{n:166, q:'De conformidad con lo dispuesto en la Ley 17/2017, la planificación, organización, desarrollo, supervisión y control de las actividades relacionadas con las diferentes modalidades de formación en las Policías Locales, corresponde...', o:{a:'A la AVSRE.',b:'Al IVASPE.',c:'A la Consellería competente en materia de Policía Local.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'b', why:{b:'El art.16 Ley 17/2017 atribuye al IVASPE la planificación, organización, desarrollo, supervisión y control de las actividades formativas de las Policías Locales.'}},
{n:167, q:'En materia de protección civil y gestión de emergencias de la Generalitat Valenciana, es competencia del IVASPE organizar e impartir los cursos de formación básica de nuevo ingreso y los de formación continua:', o:{a:'Que se establezcan legislativa o reglamentariamente para el personal de los servicios esenciales de intervención frente a emergencias.',b:'Que se establezcan reglamentariamente para el personal de los servicios complementarios de intervención.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Conforme a la normativa vigente, el IVASPE organiza e imparte la formación tanto para servicios esenciales (establecida legislativa o reglamentariamente) como complementarios de intervención.'}},
{n:168, q:'El IVASPE organizará e impartirá, al personal de los servicios esenciales de intervención frente a emergencias, los cursos de:', o:{a:'Formación básica de nuevo ingreso.',b:'Ascenso o promoción.',c:'Formación continua.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Conforme a la Ley 17/2017 y la Ley 13/2010, el IVASPE imparte al personal de los servicios esenciales cursos de formación básica, ascenso/promoción y formación continua.'}},
{n:169, q:'En materia de protección civil y gestión de emergencias de la Generalitat Valenciana, corresponde al IVASPE:', o:{a:'Promover convenios y acuerdos con los órganos competentes de las entidades locales.',b:'Mediar en conflictos de competencias formativas entre las entidades locales y las autoridades autonómicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Conforme a la Ley 13/2010, en materia de protección civil y emergencias corresponde al IVASPE promover convenios y acuerdos con los órganos competentes de las entidades locales.'}},
{n:170, q:'En materia de protección civil y gestión de emergencias de la Generalitat Valenciana, corresponde al IVASPE promover convenios y acuerdos con los órganos competentes de las entidades locales.', o:{a:'Falso, dicha competencia corresponde a la Dirección General de Protección Civil.',b:'Cierto, con el objeto de homologar los cursos que impartan.',c:'Cierto, a los efectos de su posible valoración en los procesos de selección para los servicios de intervención o, en su caso, para la promoción interna.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'Conforme a la Ley 13/2010, el IVASPE promueve convenios con entidades locales tanto para homologar cursos como para valorarlos en procesos de selección o promoción interna.'}},
{n:171, q:'El órgano autonómico al que corresponde la formación y el perfeccionamiento profesional de las Policías Locales y la investigación en esta materia es...', o:{a:'La AVSRE.',b:'La Comisión de Coordinación de Policías Locales de la Comunitat Valenciana.',c:'El Gabinete Técnico de Coordinación de Policías Locales de la Comunitat Valenciana.',d:'El IVASPE.'}, correct:'d', why:{d:'El art.15 Ley 17/2017 establece que el IVASPE es el órgano autonómico al que corresponde la formación, perfeccionamiento profesional de las Policías Locales y la investigación en esta materia.'}},
{n:172, q:'Al objeto de homologar los cursos y programas de formación policial con las titulaciones académicas exigidas para el acceso a las distintas escalas y categorías, el IVASPE...', o:{a:'Podrá promover convenios con instituciones docentes oficiales y privadas.',b:'Podrá promover convenios y acuerdos con instituciones docentes oficiales y privadas.',c:'Podrá promover convenios y acuerdos con instituciones docentes oficiales y públicas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art.16 Ley 17/2017 establece que el IVASPE podrá promover convenios y acuerdos con instituciones docentes oficiales y públicas para homologar cursos y programas de formación policial.'}},
{n:173, q:'En cuanto a actividades formativas se refiere, el IVAP coordinará con el IVASPE...', o:{a:'Su planificación.',b:'Su programación.',c:'Su homologación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Conforme a la Ley 17/2017, el IVAP coordinará con el IVASPE la planificación, programación y homologación de las actividades formativas.'}},
{n:174, q:'La calificación del periodo de prácticas de los Policías Locales de la Comunitat Valenciana corresponderá:', o:{a:'Al IVASPE.',b:'Al Ayuntamiento respectivo.',c:'A la Consellería Competente en materia de Policía.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art.16 Ley 17/2017 atribuye al IVASPE la calificación del periodo de prácticas de los Policías Locales de la Comunitat Valenciana.'}},
{n:175, q:'Con respecto al periodo de prácticas de las Policías Locales de la Comunitat Valenciana:', o:{a:'Su calificación corresponderá al IVASPE.',b:'Su valoración se hará en función de criterios objetivos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Conforme al art.16 Ley 17/2017, la calificación del periodo de prácticas corresponde al IVASPE y se realiza en función de criterios objetivos.'}},
{n:176, q:'Con respecto al periodo de prácticas de las Policías Locales de la Comunitat Valenciana, terminado el curso teórico-práctico, el IVASPE:', o:{a:'Comunicará al órgano competente de la corporación local, la relación de aspirantes de la Policía Local que lo hayan superado.',b:'Indicará a la corporación local la puntuación y las calificaciones obtenidas por los aspirantes a Policía Local, a efectos de su nombramiento como funcionarios de carrera.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.16 Ley 17/2017 establece que el IVASPE comunica la relación de quienes superan el curso e indica las calificaciones a la corporación local para el nombramiento como funcionarios de carrera.'}},
{n:177, q:'En la Comunitat Valenciana, el nombramiento de los Policías Locales que hayan superado el curso teórico practico, deben efectuarse:', o:{a:'En los quince días siguientes a su comunicación por el IVASPE.',b:'En los diez días siguientes a su comunicación por el IVASPE.',c:'En el plazo de un mes desde su comunicación por el IVASPE.',d:'En el plazo de dos meses desde su comunicación por el IVASPE.'}, correct:'a', why:{a:'El art.16 Ley 17/2017 establece que el nombramiento de los Policías Locales que hayan superado el curso teórico-práctico debe efectuarse en los quince días siguientes a su comunicación por el IVASPE.'}},
{n:178, q:'En cada convocatoria, los aspirantes a Policía Local que no superen el curso teórico práctico impartido en el IVASPE:', o:{a:'Quedarán decaídos en su derecho a participar en el próximo proceso de selección.',b:'Podrán incorporarse al curso inmediatamente posterior.',c:'Podrán incorporarse a cualquiera de los cursos posteriores, siempre que no superen el plazo de dos años desde la finalización de la oposición.',d:'Podrán incorporarse a cualquiera de los cursos posteriores, siempre que no superen el plazo de cuatro años desde la finalización de la oposición.'}, correct:'b', why:{b:'El art.16 Ley 17/2017 establece que los aspirantes que no superen el curso del IVASPE podrán incorporarse al curso inmediatamente posterior.'}},
{n:179, q:'En cada convocatoria, los aspirantes a Policía Local que no superen el curso teórico práctico impartido en el IVASPE podrán incorporarse al curso inmediatamente posterior.', o:{a:'Cierto, pero solo en dos cursos posteriores.',b:'Falso.',c:'Cierto, y de no superar este segundo curso quedarán definitivamente decaídos en su derecho a participar en el proceso de selección instado.',d:'Cierto, y de no superar este segundo, dispondrán de un plazo de dos años para realizar un último y definitivo curso.'}, correct:'c', why:{c:'El art.16 Ley 17/2017 establece que los aspirantes pueden incorporarse al curso inmediatamente posterior y, de no superarlo, quedarán definitivamente decaídos en su derecho a participar en ese proceso de selección.'}},
{n:180, q:'La selección de aspirantes a los cursos de formación y perfeccionamiento para Policías Locales de la Comunitat Valenciana es realizada por:', o:{a:'El IVASPE.',b:'La Dirección General de Interior.',c:'La Consellería competente en materia de Policía.',d:'Los Ayuntamientos respectivos.'}, correct:'a', why:{a:'El art.16 Ley 17/2017 atribuye al IVASPE la selección de aspirantes a los cursos de formación y perfeccionamiento para Policías Locales.'}},
{n:181, q:'A la vista de las instancias recibidas, la selección de aspirantes a los cursos de perfeccionamiento para Policías Locales de la Comunitat Valenciana, la realiza:', o:{a:'El IVASPE.',b:'La Dirección General de Interior.',c:'El Ayuntamiento respectivo donde presta servicio el Policía Local.',d:'La Consellería competente en materia de Policía.'}, correct:'a', why:{a:'El art.16 Ley 17/2017 establece que la selección de aspirantes a cursos de perfeccionamiento para Policías Locales la realiza el IVASPE.'}},
{n:182, q:'La selección de aspirantes a los cursos de perfeccionamiento para Policías Locales de la Comunitat Valenciana la realiza el IVASPE, atendiendo a criterios:', o:{a:'De preferencia y de capacitación.',b:'De exclusión y de preferencia.',c:'De exclusión, de preferencia y de capacitación.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art.16 Ley 17/2017 establece que la selección de aspirantes a cursos de perfeccionamiento la realiza el IVASPE atendiendo a criterios de exclusión y de preferencia.'}},
{n:183, q:'En cuanto a la inspección y seguimiento de los cursos para Policías Locales de la Comunitat Valenciana:', o:{a:'El IVASPE podrá realizar cuantas visitas de inspección y control estime necesarias al principio, durante y al finalizar los cursos.',b:'En aquellos cursos que se gestionen a través de una plataforma online se facilitará al IVASPE un usuario y una contraseña para el acceso a los mismos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art.16 Ley 17/2017 establece que el IVASPE puede realizar visitas de inspección en cualquier momento del curso y, para cursos online, se le facilita acceso con usuario y contraseña.'}},
];
